        );
    }

    #[test]
    fn random_int_is_inclusive_and_rejects_invalid_range() {
        let mut rng = DeterministicRng::new(42);
        for _ in 0..100 {
            let value = rng.next_int(-2, 2).unwrap();
            assert!((-2..=2).contains(&value));
        }
        assert!(rng.next_int(2, -2).is_err());
    }
}

//! Fixed-tick ownership and delivery for reusable batched geometry work.
use crate::spatial::{
    CpuSpatialExecutor, SpatialBatch, SpatialBatchResult, SpatialBody, SpatialExecutor, SpatialQuery,
    SpatialExecutionProfile, SpatialExecutionPhases,
    validate_batch_detailed, validate_bodies_detailed, validate_result_detailed,
};
use serde::Serialize;
use crate::diagnostics::{EngineDiagnostic, InputDiagnostic};
use super::spatial_metrics::{SpatialBindingProfile, SpatialBindingSample};
use std::{cell::{Cell, RefCell}, collections::BTreeMap, rc::Rc, time::Instant};

const MAX_INDICES: usize = 8;
const MAX_BODIES: usize = 131_072;
const MAX_TICK_SUBMISSIONS: usize = 4;
const MAX_TICKETS: usize = 16;
const MAX_SAFE_INTEGER: u64 = 9_007_199_254_740_991;

#[derive(Clone)]
struct Index {
    version: u32,
    bodies: Vec<SpatialBody>,
}

struct Ticket {
    submitted: u64,
    batch: SpatialBatch,
    dispatched: bool,
    drained: bool,
    delivered: bool,
    result: Option<SpatialBatchResult>,
    manager_ms: ManagerTimings,
}

#[derive(Clone, Default, Serialize)]
struct ManagerTimings {
    snapshot: f64,
    validation: f64,
    result_validation: f64,
    result_apply: f64,
}

#[derive(Default, Serialize)]
struct ProfileTotals {
    submitted_batches: u64,
    completed_batches: u64,
    cancelled_tickets: u64,
    failed_batches: u64,
    bodies: u64,
    queries: u64,
    pair_tests_upper_bound: u64,
    returned_hits: u64,
    input_body_bytes: u64,
    upload_bytes: u64,
    readback_bytes: u64,
    manager_ms: ManagerTimings,
    executor_ms: f64,
    executor_phases_ms: SpatialExecutionPhases,
    executor_samples: u64,
    executor_wall_samples: u64,
}

#[derive(Default)]
struct Profile {
    totals: ProfileTotals,
    last: Option<serde_json::Value>,
    bindings: SpatialBindingProfile,
}

fn elapsed_ms(started: Instant) -> f64 { started.elapsed().as_secs_f64() * 1000.0 }
fn add_count(total: &mut u64, value: u64) { *total = total.saturating_add(value).min(MAX_SAFE_INTEGER); }
fn add_time(total: &mut f64, value: f64) { *total = (*total + value).min(MAX_SAFE_INTEGER as f64); }
fn add_phase(total: &mut Option<f64>, value: Option<f64>) {
    if let Some(value) = value { *total = Some((total.unwrap_or(0.0) + value).min(MAX_SAFE_INTEGER as f64)); }
}

#[derive(Clone)]
enum Backend {
    Local(Rc<RefCell<Box<dyn SpatialExecutor>>>),
    External(String),
}

/// One immutable, validated batch for an official host's compute backend.
#[derive(Debug, Clone, Serialize)]
pub struct SpatialTask {
    pub id: u64,
    pub batch: SpatialBatch,
}

pub struct SpatialJobs {
    indices: BTreeMap<u64, Index>,
    tickets: BTreeMap<u64, Ticket>,
    outbound: Vec<u64>,
    sequence: Rc<Cell<u64>>,
    used: bool,
    backend: Backend,
    frame: u64,
    begun: bool,
    startup: bool,
    active: bool,
    submitted: usize,
    fault: Option<String>,
    profile: Profile,
    last_diagnostic: RefCell<Option<EngineDiagnostic>>,
}

impl Default for SpatialJobs {
    fn default() -> Self {
        Self::new()
    }
}

impl SpatialJobs {
    pub(crate) fn record_binding(&mut self, sample: SpatialBindingSample) {
        self.profile.bindings.record(sample);
    }

    pub fn new() -> Self {
        Self {
            indices: BTreeMap::new(),
            tickets: BTreeMap::new(),
            outbound: Vec::new(),
            sequence: Rc::new(Cell::new(0)),
            used: false,
            backend: Backend::Local(Rc::new(RefCell::new(Box::new(CpuSpatialExecutor::default())))),
            frame: 0,
            begun: false,
            startup: true,
            active: false,
            submitted: 0,
            fault: None,
            profile: Profile::default(),
            last_diagnostic: RefCell::new(None),
        }
    }

    /// Reload is transactional: old indices survive, old tickets do not.
    /// Candidates cannot submit work during onReload; their allocator commits
    /// only with the candidate, so failed reloads preserve future live handles.
    #[cfg(any(feature = "dev-tools", test))]
    pub fn reload_candidate(&self) -> Self {
        Self {
            indices: self.indices.clone(),
            tickets: BTreeMap::new(),
            outbound: Vec::new(),
            sequence: Rc::new(Cell::new(self.sequence.get())),
            used: self.used,
            backend: self.backend.clone(),
            frame: self.frame,
            begun: false,
            startup: true,
            active: false,
            submitted: 0,
            fault: None,
            profile: Profile::default(),
            last_diagnostic: RefCell::new(None),
        }
    }

    /// Diagnostics are observer state: never part of a snapshot or replay digest.
    pub fn last_diagnostic(&self) -> Option<EngineDiagnostic> {
        self.last_diagnostic.borrow().clone()
    }

    pub(crate) fn record_input(&self, operation: &str, issue: InputDiagnostic, index: Option<u64>, ticket: Option<u64>) -> String {
        let message = issue.message.clone();
        self.record(EngineDiagnostic::input(operation, issue), index, ticket);
        message
    }

    fn validation_failure(&self, operation: &str, code: &str, issue: InputDiagnostic, terminal: bool, ticket: u64) -> String {
        let message=issue.message.clone();
        let mut diagnostic=EngineDiagnostic::input(operation,issue);
        diagnostic.code=code.into();
        if terminal {
            diagnostic.recovery.retry="new_session".into();
            diagnostic.recovery.action="Repair the executor contract and create a new runtime or successfully reload.".into();
            diagnostic.terminal=true;
            diagnostic.recoverable=false;
        } else {
            diagnostic.recovery.action="Correct the host completion and resubmit this pending ticket; its state is unchanged.".into();
        }
        self.record(diagnostic,None,Some(ticket));
        message
    }

    fn record(&self, mut diagnostic: EngineDiagnostic, index: Option<u64>, ticket: Option<u64>) {
        diagnostic.context.frame = self.frame;
        diagnostic.context.index = index;
        diagnostic.context.ticket = ticket;
        *self.last_diagnostic.borrow_mut() = Some(diagnostic);
    }

    fn reject(&self, operation: &str, code: &str, message: &str, retry: &str,
        action: &str, index: Option<u64>, ticket: Option<u64>) -> String {
        let mut diagnostic = EngineDiagnostic::new(code, operation, message, retry, action);
        if code == "SPATIAL_INDEX_UNKNOWN" || code == "SPATIAL_TICKET_UNKNOWN" {
            diagnostic.path = Some(if index.is_some() { "index" } else { "ticket" }.into());
            diagnostic.actual = Some(serde_json::json!(index.or(ticket)));
            diagnostic.expected = Some(serde_json::json!("a currently live handle owned by this runtime"));
        }
        self.record(diagnostic, index, ticket);
        message.into()
    }

    fn alive(&self, operation: &str, index: Option<u64>, ticket: Option<u64>) -> Result<(), String> {
        match &self.fault {
            Some(error) => Err(self.reject(operation, "SPATIAL_FAILED", &format!("SPATIAL_FAILED: {error}"),
                "new_session", "Create a new runtime or successfully reload before issuing spatial work.", index, ticket)),
            None => Ok(()),
        }
    }

    fn write_phase(&self, operation: &str, index: Option<u64>) -> Result<(), String> {
        self.alive(operation, index, None)?;
        if !self.startup && !self.active {
            return Err(self.reject(operation, "SPATIAL_WRITE_OUTSIDE_START_OR_UPDATE", "SPATIAL_WRITE_OUTSIDE_START_OR_UPDATE",
                "next_tick", "Call this operation in start/onReload or a later update callback.", index, None));
        }
        Ok(())
    }

    fn update_phase(&self, operation: &str, ticket: Option<u64>) -> Result<(), String> {
        self.alive(operation, None, ticket)?;
        if !self.active {
            return Err(self.reject(operation, "SPATIAL_OUTSIDE_UPDATE", "SPATIAL_OUTSIDE_UPDATE",
                "next_tick", "Call this operation from a later update callback.", None, ticket));
        }
        Ok(())
    }

    fn allocate(&self, operation: &str) -> Result<u64, String> {
        let next = self.sequence.get().checked_add(1)
            .filter(|id| *id <= MAX_SAFE_INTEGER)
            .ok_or_else(|| self.reject(operation, "SPATIAL_HANDLE_EXHAUSTED", "SPATIAL_HANDLE_EXHAUSTED", "new_session", "Create a new runtime; handle identifiers cannot wrap or be reused.", None, None))?;
        self.sequence.set(next);
        Ok(next)
    }

    pub fn create(&mut self, bodies: Vec<SpatialBody>) -> Result<u64, String> {
        self.write_phase("spatial.create", None)?;
        validate_bodies_detailed(&bodies).map_err(|issue| self.record_input("spatial.create", issue, None, None))?;
        if self.indices.len() >= MAX_INDICES || self.body_count() + bodies.len() > MAX_BODIES {
            return Err(self.reject("spatial.create", "SPATIAL_INDEX_LIMIT", "SPATIAL_INDEX_LIMIT", "after_release", "Destroy an unused index or reduce the total body count, then retry.", None, None));
        }
        let id = self.allocate("spatial.create")?;
        self.used = true;
        self.indices.insert(id, Index { version: 1, bodies });
        Ok(id)
    }

    pub fn update(&mut self, id: u64, bodies: Vec<SpatialBody>) -> Result<u64, String> {
        self.write_phase("spatial.update", Some(id))?;
        let index = self.indices.get(&id).ok_or_else(|| self.reject("spatial.update", "SPATIAL_INDEX_UNKNOWN", "SPATIAL_INDEX_UNKNOWN", "after_correction", "Use a live index from spatial.create.", Some(id), None))?;
        validate_bodies_detailed(&bodies).map_err(|issue| self.record_input("spatial.update", issue, Some(id), None))?;
        if self.body_count() - index.bodies.len() + bodies.len() > MAX_BODIES {
            return Err(self.reject("spatial.update", "SPATIAL_INDEX_LIMIT", "SPATIAL_INDEX_LIMIT", "after_release", "Destroy an unused index or reduce the total body count, then retry.", Some(id), None));
        }
        let version = index.version.checked_add(1)
            .ok_or_else(|| self.reject("spatial.update", "SPATIAL_VERSION_EXHAUSTED", "SPATIAL_VERSION_EXHAUSTED", "after_release", "Destroy and recreate the index; versions cannot wrap.", Some(id), None))?;
        self.indices.insert(id, Index { version, bodies });
        Ok(u64::from(version))
    }

    pub fn destroy(&mut self, id: u64) -> Result<(), String> {
        self.write_phase("spatial.destroy", Some(id))?;
        if !self.indices.contains_key(&id) { return Err(self.reject("spatial.destroy", "SPATIAL_INDEX_UNKNOWN", "SPATIAL_INDEX_UNKNOWN", "after_correction", "Use a live index from spatial.create.", Some(id), None)); }
        self.indices.remove(&id);
        Ok(())
    }

    pub fn submit(&mut self, id: u64, queries: Vec<SpatialQuery>) -> Result<u64, String> {
        self.update_phase("spatial.submit", None)?;
        if self.submitted >= MAX_TICK_SUBMISSIONS {
            return Err(self.reject("spatial.submit", "SPATIAL_TICKET_LIMIT", "SPATIAL_TICKET_LIMIT", "next_tick", "Submit in the next update; cancelling tickets does not restore this tick's submission budget.", Some(id), None));
        }
        if self.tickets.len() >= MAX_TICKETS {
            return Err(self.reject("spatial.submit", "SPATIAL_TICKET_LIMIT", "SPATIAL_TICKET_LIMIT", "after_release", "Take or cancel retained tickets before submitting more work.", Some(id), None));
        }
        let index = self.indices.get(&id).ok_or_else(|| self.reject("spatial.submit", "SPATIAL_INDEX_UNKNOWN", "SPATIAL_INDEX_UNKNOWN", "after_correction", "Use a live index from spatial.create.", Some(id), None))?;
        let started = Instant::now();
        let batch = SpatialBatch { version: index.version, bodies: index.bodies.clone(), queries };
        let snapshot_ms = elapsed_ms(started);
        let started = Instant::now();
        validate_batch_detailed(&batch).map_err(|issue| self.record_input("spatial.submit", issue, Some(id), None))?;
        let validation_ms = elapsed_ms(started);
        let ticket = self.allocate("spatial.submit")?;
        self.used = true;
        let totals = &mut self.profile.totals;
        add_count(&mut totals.submitted_batches, 1);
        add_count(&mut totals.bodies, batch.bodies.len() as u64);
        add_count(&mut totals.queries, batch.queries.len() as u64);
        add_count(&mut totals.pair_tests_upper_bound, (batch.bodies.len() * batch.queries.len()) as u64);
        add_count(&mut totals.input_body_bytes, (8 + crate::spatial::PACKED_BODY_BYTES * batch.bodies.len()) as u64);
        add_time(&mut totals.manager_ms.snapshot, snapshot_ms);
        add_time(&mut totals.manager_ms.validation, validation_ms);
        self.tickets.insert(ticket, Ticket {
            submitted: self.frame,
            batch,
            dispatched: false,
            drained: false,
            delivered: false,
            result: None,
            manager_ms: ManagerTimings { snapshot: snapshot_ms, validation: validation_ms, ..Default::default() },
        });
        self.submitted += 1;
        Ok(ticket)
    }

    pub fn take(&mut self, id: u64) -> Result<SpatialBatchResult, String> {
        self.update_phase("spatial.take", Some(id))?;
        let entry = self.tickets.get(&id).ok_or_else(|| self.reject("spatial.take", "SPATIAL_TICKET_UNKNOWN", "SPATIAL_TICKET_UNKNOWN", "after_correction", "Use an unconsumed live ticket from spatial.submit.", None, Some(id)))?;
        if !entry.delivered {
            return Err(self.reject("spatial.take", "SPATIAL_RESULT_NEXT_TICK", "SPATIAL_RESULT_NEXT_TICK", "next_tick", "Take this ticket in the next update; do not branch gameplay on host readiness.", None, Some(id)));
        }
        Ok(self.tickets.remove(&id).expect("ticket checked above").result
            .expect("delivered ticket has a validated result"))
    }

    pub fn cancel(&mut self, id: u64) -> Result<(), String> {
        self.update_phase("spatial.cancel", Some(id))?;
        if !self.tickets.contains_key(&id) { return Err(self.reject("spatial.cancel", "SPATIAL_TICKET_UNKNOWN", "SPATIAL_TICKET_UNKNOWN", "after_correction", "Use an unconsumed live ticket from spatial.submit.", None, Some(id))); }
        self.tickets.remove(&id);
        add_count(&mut self.profile.totals.cancelled_tickets, 1);
        self.outbound.retain(|queued| *queued != id);
        Ok(())
    }

    pub fn begin(&mut self, frame: u64) -> Result<(), String> {
        self.alive("spatial.begin", None, None)?;
        if self.active || (self.begun && frame <= self.frame) {
            return Err(self.reject("spatial.begin", "SPATIAL_FRAME_INVALID", "SPATIAL_FRAME_INVALID", "after_correction", "Complete the active tick and provide a strictly increasing frame number.", None, None));
        }
        if self.tickets.values().any(|entry| entry.result.is_none()) {
            return Err(self.reject("spatial.begin", "SPATIAL_PENDING", "SPATIAL_PENDING: host must complete all previous batches before the next tick", "after_correction", "The host must complete all previous batches before advancing the fixed tick.", None, None));
        }
        for entry in self.tickets.values_mut() {
            if entry.submitted < frame {
                entry.delivered = true;
            }
        }
        self.frame = frame;
        self.begun = true;
        self.startup = false;
        self.active = true;
        self.submitted = 0;
        Ok(())
    }

    /// Close the initialization/onReload phase before the first update or view.
    pub fn loaded(&mut self) {
        self.startup = false;
    }

    pub fn finish(&mut self) -> Result<(), String> {
        self.update_phase("spatial.finish", None)?;
        self.active = false;
        let result = self.finish_inner();
        if let Err(error) = &result {
            self.fail_state(error.clone());
        }
        result
    }

    fn finish_inner(&mut self) -> Result<(), String> {
        let ids: Vec<u64> = self.tickets.iter().filter(|(_, entry)| !entry.dispatched)
            .map(|(id, _)| *id).collect();
        match &self.backend {
            Backend::Local(executor) => {
                let executor = Rc::clone(executor);
                let mut completed = Vec::with_capacity(ids.len());
                for id in &ids {
                    let batch = &self.tickets[id].batch;
                    let mut executor = executor.borrow_mut();
                    let started = Instant::now();
                    let execution = executor.execute(batch);
                    let executor_ms = elapsed_ms(started);
                    let measured = executor.take_profile();
                    let result = execution.map_err(|message| self.reject("spatial.finish", "SPATIAL_EXECUTOR_FAILED", &message, "new_session", "Inspect the executor failure and create a new runtime or successfully reload.", None, Some(*id)))?;
                    let measured = measured.or_else(|| (executor.name() == "cpu").then(|| SpatialExecutionProfile {
                        clock: "host_monotonic".into(), total_ms: executor_ms,
                        phases_ms: SpatialExecutionPhases { cpu_execute: Some(executor_ms), ..Default::default() },
                        gpu_kernel_unavailable_reason: Some("CPU backend does not dispatch GPU work".into()),
                        upload_bytes: 0, readback_bytes: 0,
                    }));
                    if let Some(profile) = &measured { profile.validate_detailed().map_err(|issue| self.validation_failure("spatial.finish", "SPATIAL_PROFILE_INVALID", issue, true, *id))?; }
                    let started = Instant::now();
                    validate_result_detailed(batch, &result).map_err(|issue| self.validation_failure("spatial.finish", "SPATIAL_RESULT_INVALID", issue, true, *id))?;
                    completed.push((*id, result, measured, executor_ms, elapsed_ms(started)));
                }
                for (id, result, measured, executor_ms, result_validation_ms) in completed {
                    let started = Instant::now();
                    let entry = self.tickets.get_mut(&id).expect("ticket cannot change during execution");
                    entry.dispatched = true;
                    entry.result = Some(result);
                    entry.manager_ms.result_validation = result_validation_ms;
                    entry.manager_ms.result_apply = elapsed_ms(started);
                    self.record_completion(id, measured, executor_ms);
                }
            }
            Backend::External(_) => {
                for id in ids {
                    self.tickets.get_mut(&id).expect("ticket checked above").dispatched = true;
                    self.outbound.push(id);
                }
            }
        }
        Ok(())
    }

    pub fn fail(&mut self, error: String) {
        self.record(EngineDiagnostic::new("SPATIAL_HOST_FAILED", "spatial.fail", &error, "new_session",
            "Inspect the host failure and create a new runtime or successfully reload."), None, None);
        self.fail_state(error);
    }

    fn fail_state(&mut self, error: String) {
        add_count(&mut self.profile.totals.failed_batches, self.tickets.values().filter(|entry| entry.result.is_none()).count() as u64);
        self.active = false;
        self.fault = Some(error);
        self.tickets.clear();
        self.outbound.clear();
    }

    pub fn set_executor(&mut self, executor: Box<dyn SpatialExecutor>) -> Result<(), String> {
        self.can_switch_backend()?;
        if executor.name().is_empty() || executor.name().len() > 64 {
            return Err(self.reject("spatial.setBackend", "SPATIAL_BACKEND_INVALID", "SPATIAL_BACKEND_INVALID", "after_correction", "Supply a nonempty backend name of at most 64 bytes.", None, None));
        }
        self.backend = Backend::Local(Rc::new(RefCell::new(executor)));
        self.profile = Profile::default();
        Ok(())
    }

    pub fn set_external_backend(&mut self, name: String) -> Result<(), String> {
        self.can_switch_backend()?;
        if name.is_empty() || name.len() > 64 {
            return Err(self.reject("spatial.setBackend", "SPATIAL_BACKEND_INVALID", "SPATIAL_BACKEND_INVALID", "after_correction", "Supply a nonempty backend name of at most 64 bytes.", None, None));
        }
        self.backend = Backend::External(name);
        self.profile = Profile::default();
        Ok(())
    }

    fn can_switch_backend(&self) -> Result<(), String> {
        self.alive("spatial.setBackend", None, None)?;
        if self.active || !self.tickets.is_empty() {
            return Err(self.reject("spatial.setBackend", "SPATIAL_BACKEND_BUSY", "SPATIAL_BACKEND_BUSY", "after_release", "Take or cancel all tickets and finish the update before changing backends.", None, None));
        }
        Ok(())
    }

    pub fn drain_tasks(&mut self) -> Vec<SpatialTask> {
        self.outbound.drain(..).filter_map(|id| {
            let entry = self.tickets.get_mut(&id)?;
            entry.drained = true;
            Some(SpatialTask { id, batch: entry.batch.clone() })
        }).collect()
    }

    pub fn complete(&mut self, id: u64, result: SpatialBatchResult) -> Result<(), String> {
        self.complete_with_profile(id, result, None)
    }

    pub fn complete_with_profile(&mut self, id: u64, result: SpatialBatchResult, profile: Option<SpatialExecutionProfile>) -> Result<(), String> {
        self.alive("spatial.complete", None, Some(id))?;
        if !matches!(self.backend, Backend::External(_)) || self.active {
            return Err(self.reject("spatial.complete", "SPATIAL_COMPLETION_OUTSIDE_HOST_PHASE", "SPATIAL_COMPLETION_OUTSIDE_HOST_PHASE", "after_correction", "Complete external work after finish and before the next begin.", None, Some(id)));
        }
        let entry = self.tickets.get(&id).ok_or_else(|| self.reject("spatial.complete", "SPATIAL_TICKET_UNKNOWN", "SPATIAL_TICKET_UNKNOWN", "after_correction", "Complete only a drained, live external ticket; discard stale host replies.", None, Some(id)))?;
        if !entry.dispatched || !entry.drained || entry.result.is_some() {
            return Err(self.reject("spatial.complete", "SPATIAL_COMPLETION_INVALID", "SPATIAL_COMPLETION_INVALID", "after_correction", "Complete each drained external ticket exactly once.", None, Some(id)));
        }
        if let Some(profile) = &profile { profile.validate_detailed().map_err(|issue| self.validation_failure("spatial.complete", "SPATIAL_PROFILE_INVALID", issue, false, id))?; }
        let started = Instant::now();
        validate_result_detailed(&entry.batch, &result).map_err(|issue| self.validation_failure("spatial.complete", "SPATIAL_RESULT_INVALID", issue, false, id))?;
        let result_validation_ms = elapsed_ms(started);
        let started = Instant::now();
        let entry = self.tickets.get_mut(&id).expect("validated ticket remains live");
        entry.result = Some(result);
        entry.manager_ms.result_validation = result_validation_ms;
        entry.manager_ms.result_apply = elapsed_ms(started);
        let executor_ms = profile.as_ref().map_or(0.0, |profile| profile.total_ms);
        self.record_completion(id, profile, executor_ms);
        Ok(())
    }

    fn record_completion(&mut self, id: u64, executor: Option<SpatialExecutionProfile>, executor_ms: f64) {
        let entry = &self.tickets[&id];
        let hits = entry.result.as_ref().expect("completion owns a result").results.iter().map(|result| result.hits.len() as u64).sum();
        let totals = &mut self.profile.totals;
        add_count(&mut totals.completed_batches, 1);
        add_count(&mut totals.returned_hits, hits);
        add_time(&mut totals.manager_ms.result_validation, entry.manager_ms.result_validation);
        add_time(&mut totals.manager_ms.result_apply, entry.manager_ms.result_apply);
        add_time(&mut totals.executor_ms, executor_ms);
        if executor.is_some() || matches!(self.backend, Backend::Local(_)) {
            add_count(&mut totals.executor_wall_samples, 1);
        }
        if let Some(sample) = &executor {
            add_count(&mut totals.executor_samples, 1);
            add_count(&mut totals.upload_bytes, sample.upload_bytes);
            add_count(&mut totals.readback_bytes, sample.readback_bytes);
            let target = &mut totals.executor_phases_ms;
            let source = &sample.phases_ms;
            add_phase(&mut target.preparation, source.preparation);
            add_phase(&mut target.queue_wait, source.queue_wait);
            add_phase(&mut target.validation, source.validation);
            add_phase(&mut target.packing, source.packing);
            add_phase(&mut target.upload, source.upload);
            add_phase(&mut target.encode_submit, source.encode_submit);
            add_phase(&mut target.readback_wait, source.readback_wait);
            add_phase(&mut target.decode, source.decode);
            add_phase(&mut target.cpu_execute, source.cpu_execute);
            add_phase(&mut target.gpu_kernel, source.gpu_kernel);
        }
        self.profile.last = Some(serde_json::json!({
            "ticket": id, "version": entry.batch.version,
            "bodies": entry.batch.bodies.len(), "queries": entry.batch.queries.len(),
            "pair_tests_upper_bound": entry.batch.bodies.len() * entry.batch.queries.len(),
            "returned_hits": hits, "manager_ms": entry.manager_ms,
            "executor_ms": if executor.is_some() || matches!(self.backend, Backend::Local(_)) { Some(executor_ms) } else { None },
            "executor": executor,
            "executor_unavailable_reason": if executor.is_none() { Some("This executor did not provide phase diagnostics; local executor_ms remains measured when available") } else { None },
        }));
    }

    /// Detached, bounded diagnostics. Reading never consumes tickets or changes
    /// execution policy. Timings are intentionally excluded from `snapshot`.
    pub fn profile(&self) -> serde_json::Value {
        let backend = match &self.backend {
            Backend::Local(executor) => executor.borrow().name().to_string(),
            Backend::External(name) => name.clone(),
        };
        serde_json::json!({
            "api_version": 1, "backend": backend, "clock": "host_monotonic",
            "scope": "Successful submissions and completed batches since backend selection or successful reload; invalid API attempts excluded. Manager timings exclude Luau conversion. Executor phases are host wall time, may overlap, and are not GPU kernel time. Pair tests are an upper bound, not measured visits. input_body_bytes is equivalent USB1 payload size, not allocation traffic.",
            "limits": { "retained_completed_batches": 1, "counter_max": MAX_SAFE_INTEGER },
            "totals": self.profile.totals, "last": self.profile.last,
            "bindings": self.profile.bindings,
        })
    }

    fn body_count(&self) -> usize {
        self.indices.values().map(|index| index.bodies.len()).sum()
    }

    /// Canonical inputs describe future observable work without exposing host
    /// scheduling, backend identity, or the timing of an early completion.
    pub fn snapshot(&self) -> Option<serde_json::Value> {
        if !self.used {
            return None;
        }
        Some(serde_json::json!({
            "sequence": self.sequence.get(),
            "indices": self.indices.iter().map(|(id, index)| serde_json::json!({
                "id": id, "version": index.version, "bodies": index.bodies,
            })).collect::<Vec<_>>(),
            "tickets": self.tickets.iter().map(|(id, entry)| serde_json::json!({
                "id": id, "submit_tick": entry.submitted,
                "delivered": entry.delivered, "batch": entry.batch,
            })).collect::<Vec<_>>(),
        }))
    }

    pub fn info(&self) -> serde_json::Value {
        let (backend, external) = match &self.backend {
            Backend::Local(executor) => (executor.borrow().name().to_string(), false),
            Backend::External(name) => (name.clone(), true),
        };
        serde_json::json!({
            "api_version": 1,
            "backend": backend,
            "external": external,
            "delivery": "next_tick",
            "packed_format": "USB1",
            "operations": ["nearest", "overlap_sphere", "sweep_sphere"],
            "indices": self.indices.len(),
            "bodies": self.body_count(),
            "tickets": self.tickets.len(),
            "pending": self.tickets.values().filter(|entry| entry.result.is_none()).count(),
            "fault": self.fault,
            "limits": {
                "indices": MAX_INDICES,
                "bodies": MAX_BODIES,
                "bodies_per_index": crate::spatial::MAX_BODIES,
                "queries_per_batch": crate::spatial::MAX_QUERIES,
                "hits_per_query": crate::spatial::MAX_HITS,
                "coordinate_abs": crate::spatial::MAX_COORDINATE,
                "submissions_per_tick": MAX_TICK_SUBMISSIONS,
                "tickets": MAX_TICKETS,
                "safe_integer": MAX_SAFE_INTEGER,
            },
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn body(id: u32, x: f32) -> SpatialBody {
        SpatialBody { id, position: [x, 0.0, 0.0], radius: 1.0, category: 1, previous_position: None }
    }

    fn nearest() -> SpatialQuery {
        SpatialQuery::Nearest { point: [0.0; 3], max_distance: 100.0, mask: u32::MAX, exclude_id: None }
    }

    #[test]
    fn structured_input_facts_are_one_based_atomic_and_detached_from_state() {
        let mut jobs = SpatialJobs::new();
        let id = jobs.create(vec![body(3, 0.0)]).unwrap();
        let snapshot = jobs.snapshot();
        let profile = jobs.profile();
        let mut invalid = body(4, 0.0);
        invalid.radius = f32::NAN;
        assert_eq!(jobs.update(id, vec![invalid]).unwrap_err(), "bodies[0].radius must be finite and in 0..=1000000");
        let diagnostic = jobs.last_diagnostic().unwrap();
        assert_eq!(diagnostic.code, "SPATIAL_INPUT_INVALID");
        assert_eq!(diagnostic.operation, "spatial.update");
        assert_eq!(diagnostic.path.as_deref(), Some("bodies[1].radius"));
        assert_eq!(diagnostic.actual, Some(serde_json::json!("NaN")));
        assert_eq!(diagnostic.expected.as_ref().unwrap()["min"], 0);
        assert_eq!(diagnostic.context.index, Some(id));
        assert_eq!(diagnostic.recovery.retry, "after_correction");
        assert!(diagnostic.recoverable && !diagnostic.terminal);
        assert_eq!(snapshot, jobs.snapshot());
        assert_eq!(profile, jobs.profile());
        let mut detached = jobs.last_diagnostic().unwrap();
        detached.code = "caller mutation".into();
        assert_eq!(jobs.last_diagnostic().unwrap(), diagnostic);
        jobs.update(id, vec![body(5, 0.0)]).unwrap();
        assert_eq!(jobs.last_diagnostic().unwrap(), diagnostic);
    }

    #[test]
    fn lifecycle_diagnostics_distinguish_next_tick_and_unknown_ticket() {
        let mut jobs = SpatialJobs::new();
        let index = jobs.create(vec![body(3, 0.0)]).unwrap();
        jobs.begin(10).unwrap();
        let ticket = jobs.submit(index, vec![nearest()]).unwrap();
        assert_eq!(jobs.take(ticket).unwrap_err(), "SPATIAL_RESULT_NEXT_TICK");
        let early = jobs.last_diagnostic().unwrap();
        assert_eq!(early.context.frame, 10);
        assert_eq!(early.context.ticket, Some(ticket));
        assert_eq!(early.recovery.retry, "next_tick");
        jobs.finish().unwrap();
        jobs.begin(11).unwrap();
        jobs.take(ticket).unwrap();
        assert_eq!(jobs.last_diagnostic().unwrap(), early);
        assert_eq!(jobs.take(ticket).unwrap_err(), "SPATIAL_TICKET_UNKNOWN");
        let consumed = jobs.last_diagnostic().unwrap();
        assert_eq!(consumed.path.as_deref(), Some("ticket"));
        assert_eq!(consumed.actual, Some(serde_json::json!(ticket)));
        assert_eq!(consumed.context.frame, 11);
        assert_eq!(consumed.recovery.retry, "after_correction");
    }

    #[test]
    fn host_result_and_profile_diagnostics_preserve_the_pending_completion() {
        let mut jobs = SpatialJobs::new();
        jobs.set_external_backend("test-gpu".into()).unwrap();
        let index = jobs.create(vec![body(3, 0.0)]).unwrap();
        jobs.begin(10).unwrap();
        let ticket = jobs.submit(index, vec![nearest()]).unwrap();
        jobs.finish().unwrap();
        let task = jobs.drain_tasks().pop().unwrap();
        let result = CpuSpatialExecutor.execute(&task.batch).unwrap();
        let before = jobs.snapshot();
        let profile_before = jobs.profile();
        let mut invalid = result.clone();
        invalid.version += 1;
        assert_eq!(jobs.complete(ticket, invalid).unwrap_err(), "spatial result version does not match the batch");
        let diagnostic = jobs.last_diagnostic().unwrap();
        assert_eq!(diagnostic.code, "SPATIAL_RESULT_INVALID");
        assert_eq!(diagnostic.path.as_deref(), Some("result.version"));
        assert_eq!(diagnostic.actual, Some(serde_json::json!(task.batch.version + 1)));
        assert_eq!(diagnostic.expected, Some(serde_json::json!(task.batch.version)));
        let profile = SpatialExecutionProfile {
            clock: "host_monotonic".into(), total_ms: f64::INFINITY,
            phases_ms: SpatialExecutionPhases::default(),
            gpu_kernel_unavailable_reason: Some("unavailable in fixture".into()),
            upload_bytes: 0, readback_bytes: 0,
        };
        assert!(jobs.complete_with_profile(ticket, result.clone(), Some(profile)).unwrap_err().starts_with("SPATIAL_PROFILE_INVALID:"));
        let diagnostic = jobs.last_diagnostic().unwrap();
        assert_eq!(diagnostic.path.as_deref(), Some("profile.total_ms"));
        assert_eq!(diagnostic.actual, Some(serde_json::json!("inf")));
        assert!(diagnostic.recoverable && !diagnostic.terminal);
        assert_eq!(before, jobs.snapshot());
        assert_eq!(profile_before, jobs.profile());
        jobs.complete(ticket, result).unwrap();
        assert_eq!(jobs.last_diagnostic().unwrap(), diagnostic);
    }

    #[test]
    fn terminal_failures_are_bounded_and_failed_reload_preserves_live_diagnostics() {
        struct Failing;
        impl SpatialExecutor for Failing {
            fn name(&self) -> &str { "failure-fixture" }
            fn execute(&mut self, _: &SpatialBatch) -> Result<SpatialBatchResult, String> { Err("測".repeat(10_000)) }
        }
        let mut jobs = SpatialJobs::new();
        jobs.set_executor(Box::new(Failing)).unwrap();
        let index = jobs.create(vec![body(3, 0.0)]).unwrap();
        jobs.begin(1).unwrap();
        let ticket = jobs.submit(index, vec![nearest()]).unwrap();
        assert_eq!(jobs.finish().unwrap_err(), "測".repeat(10_000));
        let diagnostic = jobs.last_diagnostic().unwrap();
        assert_eq!(diagnostic.code, "SPATIAL_EXECUTOR_FAILED");
        assert_eq!(diagnostic.context.ticket, Some(ticket));
        assert!(!diagnostic.recoverable && diagnostic.terminal);
        assert_eq!(diagnostic.recovery.retry, "new_session");
        assert!(serde_json::to_vec(&diagnostic).unwrap().len() < 4096);
        let candidate = jobs.reload_candidate();
        assert!(candidate.last_diagnostic().is_none());
        assert_eq!(jobs.last_diagnostic().unwrap(), diagnostic);
        let mut candidate = candidate;
        candidate.destroy(index + 100).unwrap_err();
        assert_eq!(jobs.last_diagnostic().unwrap(), diagnostic);
        // A successful reload replaces observer state, just like its profile.
        jobs = jobs.reload_candidate();
        assert!(jobs.last_diagnostic().is_none());
    }

    #[test]
    fn versions_are_frozen_and_tickets_deliver_once_on_next_tick() {
        let mut jobs = SpatialJobs::new();
        assert!(jobs.snapshot().is_none());
        let index = jobs.create(vec![body(5, 5.0)]).unwrap();
        assert!(jobs.submit(index, vec![nearest()]).unwrap_err().contains("OUTSIDE_UPDATE"));
        jobs.begin(0).unwrap();
        assert_eq!(jobs.update(index, vec![body(2, 2.0)]).unwrap(), 2);
        let ticket = jobs.submit(index, vec![nearest()]).unwrap();
        jobs.update(index, vec![body(8, 8.0)]).unwrap();
        jobs.destroy(index).unwrap();
        assert!(jobs.take(ticket).unwrap_err().contains("NEXT_TICK"));
        jobs.finish().unwrap();
        assert!(jobs.take(ticket).unwrap_err().contains("OUTSIDE_UPDATE"));
        assert!(jobs.create(Vec::new()).unwrap_err().contains("OUTSIDE_START_OR_UPDATE"));
        jobs.begin(1).unwrap();
        let result = jobs.take(ticket).unwrap();
        assert_eq!(result.version, 2);
        assert_eq!(result.results[0].hits[0].id, 2);
        assert!(jobs.take(ticket).unwrap_err().contains("UNKNOWN"));
        jobs.finish().unwrap();
    }

    #[test]
    fn external_barrier_rejects_missing_duplicate_and_invalid_completions() {
        let mut jobs = SpatialJobs::new();
        jobs.set_external_backend("test-gpu".into()).unwrap();
        let index = jobs.create(vec![body(3, 1.0)]).unwrap();
        jobs.begin(10).unwrap();
        let ticket = jobs.submit(index, vec![nearest()]).unwrap();
        assert!(jobs.drain_tasks().is_empty());
        jobs.finish().unwrap();
        assert!(jobs.begin(11).unwrap_err().contains("SPATIAL_PENDING"));
        let guessed = CpuSpatialExecutor.execute(&jobs.tickets[&ticket].batch).unwrap();
        assert!(jobs.complete(ticket, guessed).is_err());
        let task = jobs.drain_tasks().pop().unwrap();
        assert_eq!(task.id, ticket);
        assert!(jobs.drain_tasks().is_empty());
        let result = CpuSpatialExecutor.execute(&task.batch).unwrap();
        let mut invalid = result.clone();
        invalid.version += 1;
        assert!(jobs.complete(ticket, invalid).is_err());
        let mut invalid = result.clone();
        invalid.results[0].hits[0].id = 99;
        assert!(jobs.complete(ticket, invalid).is_err());
        assert!(jobs.complete(ticket + 1, result.clone()).is_err());
        jobs.complete(ticket, result.clone()).unwrap();
        assert!(jobs.complete(ticket, result.clone()).is_err());
        jobs.begin(11).unwrap();
        assert_eq!(jobs.take(ticket).unwrap(), result);
        jobs.finish().unwrap();
    }

    #[test]
    fn cancelled_and_failed_ticks_never_dispatch_work() {
        let mut jobs = SpatialJobs::new();
        jobs.set_external_backend("test-gpu".into()).unwrap();
        let index = jobs.create(Vec::new()).unwrap();
        jobs.begin(0).unwrap();
        let cancelled = jobs.submit(index, Vec::new()).unwrap();
        jobs.cancel(cancelled).unwrap();
        let failed = jobs.submit(index, Vec::new()).unwrap();
        assert!(failed > cancelled);
        jobs.fail("script failed".into());
        assert!(jobs.drain_tasks().is_empty());
        assert!(jobs.finish().is_err());
        assert!(jobs.begin(1).is_err());
        assert!(jobs.create(Vec::new()).is_err());
    }

    #[test]
    fn limits_and_invalid_updates_are_atomic() {
        let mut jobs = SpatialJobs::new();
        let first = jobs.create(vec![body(1, 0.0)]).unwrap();
        let snapshot = jobs.snapshot();
        assert!(jobs.update(first, vec![body(2, 0.0), body(2, 1.0)]).is_err());
        assert_eq!(jobs.snapshot(), snapshot);
        for _ in 1..MAX_INDICES { jobs.create(Vec::new()).unwrap(); }
        assert!(jobs.create(Vec::new()).is_err());
        jobs.begin(0).unwrap();
        for _ in 0..MAX_TICK_SUBMISSIONS {
            let ticket = jobs.submit(first, Vec::new()).unwrap();
            jobs.cancel(ticket).unwrap();
        }
        assert!(jobs.submit(first, Vec::new()).is_err());
        jobs.finish().unwrap();
    }

    #[test]
    fn startup_closes_before_first_update_and_outstanding_tickets_are_bounded() {
        let mut jobs = SpatialJobs::new();
        let index = jobs.create(Vec::new()).unwrap();
        jobs.loaded();
        assert!(jobs.create(Vec::new()).is_err());
        assert!(jobs.update(index, Vec::new()).is_err());
        assert!(jobs.destroy(index).is_err());
        let mut first_ticket = None;
        for frame in 0..4 {
            jobs.begin(frame).unwrap();
            for _ in 0..4 {
                let ticket = jobs.submit(index, Vec::new()).unwrap();
                first_ticket.get_or_insert(ticket);
            }
            jobs.finish().unwrap();
        }
        jobs.begin(4).unwrap();
        assert!(jobs.submit(index, Vec::new()).unwrap_err().contains("TICKET_LIMIT"));
        jobs.cancel(first_ticket.unwrap()).unwrap();
        jobs.submit(index, Vec::new()).unwrap();
        jobs.finish().unwrap();
    }

    #[test]
    fn reload_preserves_indices_and_isolates_uncommitted_candidate_ids() {
        let mut jobs = SpatialJobs::new();
        let index = jobs.create(vec![body(7, 1.0)]).unwrap();
        jobs.begin(0).unwrap();
        let old_ticket = jobs.submit(index, vec![nearest()]).unwrap();
        jobs.finish().unwrap();
        let mut candidate = jobs.reload_candidate();
        assert_eq!(candidate.update(index, vec![body(9, 1.0)]).unwrap(), 2);
        let candidate_index = candidate.create(Vec::new()).unwrap();
        candidate.begin(1).unwrap();
        assert!(candidate.take(old_ticket).is_err());
        let candidate_ticket = candidate.submit(index, vec![nearest()]).unwrap();
        candidate.finish().unwrap();
        jobs.begin(1).unwrap();
        assert_eq!(jobs.take(old_ticket).unwrap().results[0].hits[0].id, 7);
        assert_eq!(jobs.create(Vec::new()).unwrap(), old_ticket + 1);
        assert!(candidate_index > old_ticket);
        candidate.begin(2).unwrap();
        assert!(candidate.create(Vec::new()).unwrap() > candidate_ticket);
        candidate.finish().unwrap();
    }

    #[test]
    fn failed_reload_first_use_does_not_change_live_snapshot() {
        let jobs = SpatialJobs::new();
        let mut candidate = jobs.reload_candidate();
        candidate.create(Vec::new()).unwrap();
        assert!(jobs.snapshot().is_none());
        assert_eq!(jobs.sequence.get(), 0);
    }

    #[test]
    fn canonical_snapshot_captures_future_handle_sequence() {
        let mut first = SpatialJobs::new();
        let mut second = SpatialJobs::new();
        let id = first.create(Vec::new()).unwrap();first.destroy(id).unwrap();
        for _ in 0..2 { let id=second.create(Vec::new()).unwrap();second.destroy(id).unwrap(); }
        assert_ne!(first.snapshot(), second.snapshot());
    }

    #[test]
    fn handle_and_version_exhaustion_do_not_wrap_or_mutate_data() {
        let mut jobs = SpatialJobs::new();
        jobs.sequence.set(MAX_SAFE_INTEGER - 1);
        let index = jobs.create(vec![body(1, 1.0)]).unwrap();
        assert_eq!(index, MAX_SAFE_INTEGER);
        assert!(jobs.create(Vec::new()).unwrap_err().contains("HANDLE_EXHAUSTED"));
        jobs.indices.get_mut(&index).unwrap().version = u32::MAX;
        let before = jobs.snapshot();
        assert!(jobs.update(index, vec![body(2, 2.0)]).unwrap_err().contains("VERSION_EXHAUSTED"));
        assert_eq!(jobs.snapshot(), before);
    }

    #[test]
    fn snapshot_hides_host_completion_timing_and_backend() {
        let mut cpu = SpatialJobs::new();
        let mut external = SpatialJobs::new();
        external.set_external_backend("test-gpu".into()).unwrap();
        for jobs in [&mut cpu, &mut external] {
            let index = jobs.create(vec![body(1, 1.0)]).unwrap();
            jobs.begin(0).unwrap();
            jobs.submit(index, vec![nearest()]).unwrap();
            jobs.finish().unwrap();
        }
        assert_eq!(cpu.snapshot(), external.snapshot());
        let task = external.drain_tasks().pop().unwrap();
        external.complete(task.id, CpuSpatialExecutor.execute(&task.batch).unwrap()).unwrap();
        assert_eq!(cpu.snapshot(), external.snapshot());
        cpu.begin(1).unwrap();
        external.begin(1).unwrap();
        assert_eq!(cpu.snapshot(), external.snapshot());
    }

    #[test]
    fn profiling_is_non_consuming_bounded_and_excluded_from_canonical_state() {
        let mut first = SpatialJobs::new();
        let mut second = SpatialJobs::new();
        for jobs in [&mut first, &mut second] {
            let index = jobs.create(vec![body(1, 1.0), body(2, 5.0)]).unwrap();
            jobs.begin(0).unwrap();
            jobs.submit(index, vec![nearest()]).unwrap();
            jobs.finish().unwrap();
        }
        let snapshot = first.snapshot();
        let profile = first.profile();
        assert_eq!(first.profile(), profile);
        assert_eq!(first.snapshot(), snapshot);
        assert_eq!(first.snapshot(), second.snapshot());
        assert_eq!(profile["totals"]["submitted_batches"], 1);
        assert_eq!(profile["totals"]["completed_batches"], 1);
        assert_eq!(profile["totals"]["pair_tests_upper_bound"], 2);
        assert_eq!(profile["totals"]["returned_hits"], 1);
        assert_eq!(profile["totals"]["input_body_bytes"], 88);
        assert_eq!(profile["last"]["executor"]["phases_ms"]["gpu_kernel"], serde_json::Value::Null);
        assert!(profile["last"]["executor"]["gpu_kernel_unavailable_reason"].is_string());
        first.begin(1).unwrap(); second.begin(1).unwrap();
        assert_eq!(first.take(2).unwrap(), second.take(2).unwrap());
        assert_eq!(first.profile(), profile);
        first.finish().unwrap(); second.finish().unwrap();
        first.set_executor(Box::new(CpuSpatialExecutor)).unwrap();
        assert_eq!(first.profile()["totals"]["completed_batches"], 0);
        assert!(first.profile()["last"].is_null());
        assert_eq!(first.snapshot(), second.snapshot());
    }

    #[test]
    fn optional_external_profiles_are_validated_atomically_and_old_hosts_still_work() {
        let mut jobs = SpatialJobs::new();
        jobs.set_external_backend("old-host".into()).unwrap();
        let index = jobs.create(vec![body(1, 1.0)]).unwrap();
        jobs.begin(0).unwrap();
        let ticket = jobs.submit(index, vec![nearest()]).unwrap();
        jobs.finish().unwrap();
        let task = jobs.drain_tasks().pop().unwrap();
        let result = CpuSpatialExecutor.execute(&task.batch).unwrap();
        let mut sample = SpatialExecutionProfile {
            clock: "host_monotonic".into(), total_ms: 1.0, phases_ms: Default::default(),
            gpu_kernel_unavailable_reason: Some("No GPU timestamp support".into()),
            upload_bytes: 16, readback_bytes: 16,
        };
        let before = jobs.profile(); let snapshot = jobs.snapshot();
        for invalid in [f64::NAN, f64::INFINITY, -1.0, 3_600_001.0] {
            sample.total_ms = invalid;
            assert!(jobs.complete_with_profile(ticket, result.clone(), Some(sample.clone())).unwrap_err().contains("PROFILE_INVALID"));
            assert_eq!(jobs.profile(), before); assert_eq!(jobs.snapshot(), snapshot);
        }
        sample.total_ms = 1.0; sample.phases_ms.upload = Some(-1.0);
        assert!(jobs.complete_with_profile(ticket, result.clone(), Some(sample.clone())).is_err());
        sample.phases_ms.upload = None; sample.upload_bytes = 1_073_741_825;
        assert!(jobs.complete_with_profile(ticket, result.clone(), Some(sample)).is_err());
        jobs.complete(ticket, result.clone()).unwrap();
        let profile = jobs.profile();
        assert!(profile["last"]["executor"].is_null());
        assert!(profile["last"]["executor_ms"].is_null());
        assert!(profile["last"]["executor_unavailable_reason"].is_string());
        assert_eq!(profile["totals"]["executor_wall_samples"], 0);
        jobs.begin(1).unwrap(); assert_eq!(jobs.take(ticket).unwrap(), result);
        let ticket = jobs.submit(index, vec![nearest()]).unwrap(); jobs.finish().unwrap();
        let task = jobs.drain_tasks().pop().unwrap();
        let result = CpuSpatialExecutor.execute(&task.batch).unwrap();
        let sample = SpatialExecutionProfile {
            clock: "host_monotonic".into(), total_ms: 3.0,
            phases_ms: SpatialExecutionPhases { readback_wait: Some(2.0), ..Default::default() },
            gpu_kernel_unavailable_reason: Some("GPU timestamp queries unavailable".into()),
            upload_bytes: 128, readback_bytes: 4096,
        };
        let snapshot = jobs.snapshot();
        jobs.complete_with_profile(ticket, result, Some(sample.clone())).unwrap();
        assert_eq!(jobs.snapshot(), snapshot);
        let profile = jobs.profile();
        assert_eq!(profile["totals"]["executor_wall_samples"], 1);
        assert_eq!(profile["totals"]["executor_samples"], 1);
        assert_eq!(profile["totals"]["executor_ms"], 3.0);
        assert_eq!(profile["totals"]["readback_bytes"], 4096);
        assert_eq!(profile["last"]["executor"], serde_json::to_value(sample).unwrap());
    }

    #[test]
    fn diagnostic_counters_reset_on_committed_reload_and_failures_do_not_leak_from_candidates() {
        let mut jobs = SpatialJobs::new();
        let index = jobs.create(Vec::new()).unwrap();
        jobs.begin(0).unwrap();
        let ticket = jobs.submit(index, Vec::new()).unwrap();
        jobs.cancel(ticket).unwrap();
        jobs.finish().unwrap();
        let original = jobs.profile();
        let mut candidate = jobs.reload_candidate();
        assert_eq!(candidate.profile()["totals"]["submitted_batches"], 0);
        candidate.begin(1).unwrap(); candidate.submit(index, Vec::new()).unwrap();
        candidate.fail("candidate failure".into());
        assert_eq!(candidate.profile()["totals"]["failed_batches"], 1);
        assert_eq!(jobs.profile(), original);
        assert_eq!(original["totals"]["cancelled_tickets"], 1);
        assert_eq!(original["totals"]["completed_batches"], 0);
        let committed = jobs.reload_candidate();
        assert_eq!(committed.profile()["totals"]["submitted_batches"], 0);
        assert!(committed.profile()["last"].is_null());
        let mut total = MAX_SAFE_INTEGER - 1;
        add_count(&mut total, 10); assert_eq!(total, MAX_SAFE_INTEGER);
    }
}

//! Bounded diagnostics for Lua/Rust conversion, detached from canonical state.
use serde::Serialize;
const MAX: f64 = 9_007_199_254_740_991.0;

#[derive(Clone, Serialize)]
pub(crate) struct SpatialBindingSample {
    pub operation: &'static str,
    pub success: bool,
    pub input_decode_ms: f64,
    pub output_encode_ms: f64,
    pub index: Option<u64>,
    pub ticket: Option<u64>,
}

#[derive(Serialize)]
pub(crate) struct SpatialBindingProfile {
    clock: &'static str,
    scope: &'static str,
    calls: u64,
    failed_calls: u64,
    input_decode_ms: f64,
    output_encode_ms: f64,
    last: Option<SpatialBindingSample>,
}

impl Default for SpatialBindingProfile {
    fn default() -> Self {
        Self { clock: "host_monotonic", scope: "Since backend selection or successful reload. pack/create/update/destroy/submit/take/cancel attempts only. Input conversion includes schema checks and failed-input diagnostic construction; output conversion includes packed buffer creation or result JSON-to-Lua conversion. Excludes manager/executor, observation publication and lastDiagnostic/info/profile serialization. Latest operation is independent of latest completed batch.", calls: 0, failed_calls: 0, input_decode_ms: 0.0, output_encode_ms: 0.0, last: None }
    }
}

impl SpatialBindingProfile {
    pub fn record(&mut self, sample: SpatialBindingSample) {
        self.calls = self.calls.saturating_add(1).min(MAX as u64);
        if !sample.success { self.failed_calls = self.failed_calls.saturating_add(1).min(MAX as u64); }
        self.input_decode_ms = (self.input_decode_ms + sample.input_decode_ms).min(MAX);
        self.output_encode_ms = (self.output_encode_ms + sample.output_encode_ms).min(MAX);
        self.last = Some(sample);
    }
}

//! Portable table/buffer boundary for the batched geometry API.
use super::{ApiState, Lua, Table, Value};
use crate::diagnostics::InputDiagnostic;
use crate::runtime::spatial::SpatialJobs;
use crate::runtime::spatial_metrics::SpatialBindingSample;
use crate::spatial::{SpatialBody, SpatialQuery, pack_bodies, unpack_bodies_detailed, validate_bodies_detailed};
use serde::{Serialize, de::DeserializeOwned};
use std::{cell::RefCell, collections::BTreeMap, rc::Rc, time::Instant};

const MAX_SAFE_INTEGER: f64 = 9_007_199_254_740_991.0;
type InputResult<T> = Result<T, InputDiagnostic>;

fn invalid(message: impl std::fmt::Display, path: &str, actual: serde_json::Value, expected: serde_json::Value) -> InputDiagnostic {
    InputDiagnostic::new(format!("SPATIAL_INPUT_INVALID: {message}"), path, actual, expected)
}

fn value_fact(value: &Value) -> serde_json::Value {
    match value {
        Value::Nil => serde_json::Value::Null,
        Value::Boolean(value) => (*value).into(),
        Value::Integer(value) => serde_json::json!(value),
        Value::Number(value) if value.is_finite() => serde_json::json!(value),
        Value::Number(value) => serde_json::json!(value.to_string()),
        Value::String(value) => serde_json::json!(value.to_string_lossy().chars().take(128).collect::<String>()),
        other => serde_json::json!({"type":other.type_name()}),
    }
}

fn to_json(value: Value, depth: usize, path: &str) -> InputResult<serde_json::Value> {
    if depth > 16 {
        return Err(invalid("table nesting exceeds 16", path, serde_json::json!(depth), serde_json::json!({"max_depth":16})));
    }
    match value {
        Value::Nil => Ok(serde_json::Value::Null),
        Value::Boolean(value) => Ok(value.into()),
        Value::Integer(value) => Ok(serde_json::json!(value)),
        Value::Number(value) if value.is_finite() => {
            if value.fract() == 0.0 && value.abs() <= MAX_SAFE_INTEGER {
                Ok(if value >= 0.0 { serde_json::json!(value as u64) } else { serde_json::json!(value as i64) })
            } else { Ok(serde_json::json!(value)) }
        }
        Value::Number(value) => Err(invalid("numbers must be finite", path, serde_json::json!(value.to_string()), serde_json::json!({"finite":true}))),
        Value::String(value) => value.to_str().map(|value| serde_json::json!(value.to_string()))
            .map_err(|message| invalid(message, path, serde_json::json!({"type":"string"}), serde_json::json!("UTF-8 string"))),
        Value::Table(table) => {
            let mut object = BTreeMap::new(); let mut array = BTreeMap::new();
            for pair in table.pairs::<Value, Value>() {
                let (key, value) = pair.map_err(|message| invalid(message, path, serde_json::json!({"type":"table"}), serde_json::json!("readable table")))?;
                match key {
                    Value::String(key) if array.is_empty() => {
                        let key = key.to_str().map_err(|message| invalid(message, path, serde_json::json!("invalid UTF-8 key"), serde_json::json!("UTF-8 field")))?.to_string();
                        let field_path = format!("{path}.{key}");
                        object.insert(key, to_json(value, depth + 1, &field_path)?);
                    }
                    Value::Integer(key) if key > 0 && object.is_empty() => {
                        array.insert(key as u64, to_json(value, depth + 1, &format!("{path}[{key}]"))?);
                    }
                    Value::Number(key) if key.is_finite() && key > 0.0 && key <= MAX_SAFE_INTEGER && key.fract() == 0.0 && object.is_empty() => {
                        array.insert(key as u64, to_json(value, depth + 1, &format!("{path}[{}]", key as u64))?);
                    }
                    other => return Err(invalid("use string fields or a contiguous array, without mixing keys", path,
                        value_fact(&other), serde_json::json!("string fields or contiguous positive integer array keys, without mixing"))),
                }
            }
            if array.is_empty() { Ok(serde_json::Value::Object(object.into_iter().collect())) }
            else {
                if !array.keys().copied().eq(1..=array.len() as u64) {
                    return Err(invalid("array keys must be contiguous starting at 1", path,
                        serde_json::json!(array.keys().take(16).collect::<Vec<_>>()), serde_json::json!({"first_index":1,"contiguous":true})));
                }
                Ok(serde_json::Value::Array(array.into_values().collect()))
            }
        }
        other => Err(invalid(format!("unsupported value {}", other.type_name()), path, value_fact(&other), serde_json::json!("JSON-compatible table fields"))),
    }
}

// Structural facts are generated from the schema, never by parsing serde's
// wording. The original serde error remains the thrown compatibility message.
trait InputSchema {
    const ROOT: &'static str;
    fn schema_issue(value: &serde_json::Value) -> Option<(String, serde_json::Value, serde_json::Value)>;
}

fn record_issue(value: &serde_json::Value, root: &str, allowed: &[&str], required: &[&str]) -> Option<(String, serde_json::Value, serde_json::Value)> {
    let Some(object) = value.as_object() else { return Some((root.into(), value.clone(), serde_json::json!("record"))); };
    for key in object.keys() {
        if !allowed.contains(&key.as_str()) { return Some((format!("{root}.{key}"), object[key].clone(), serde_json::json!({"allowed_fields":allowed}))); }
    }
    for field in required {
        if !object.contains_key(*field) { return Some((format!("{root}.{field}"), serde_json::Value::Null, serde_json::json!({"required":true}))); }
    }
    for (field, value) in object {
        let path = format!("{root}.{field}");
        if ["id","category","mask","exclude_id"].contains(&field.as_str()) && !(field == "exclude_id" && value.is_null()) {
            if !value.as_u64().is_some_and(|n| n <= u32::MAX as u64) { return Some((path, value.clone(), serde_json::json!({"type":"integer","min":0,"max":u32::MAX}))); }
        }
        if ["position","previous_position","point","center","from","to"].contains(&field.as_str()) && !(field == "previous_position" && value.is_null()) {
            let Some(array) = value.as_array().filter(|array| array.len() == 3) else { return Some((path, value.clone(), serde_json::json!({"type":"number_array","count":3}))); };
            for (index, coordinate) in array.iter().enumerate() {
                if !coordinate.is_number() { return Some((format!("{path}[{}]",index+1), coordinate.clone(), serde_json::json!("finite number"))); }
            }
        }
        if ["radius","max_distance"].contains(&field.as_str()) && !value.is_number() { return Some((path, value.clone(), serde_json::json!("finite number"))); }
    }
    None
}

impl InputSchema for SpatialBody {
    const ROOT: &'static str = "bodies";
    fn schema_issue(value: &serde_json::Value) -> Option<(String, serde_json::Value, serde_json::Value)> {
        record_issue(value, "", &["id","category","position","radius","previous_position"], &["id","position","radius"])
    }
}
impl InputSchema for SpatialQuery {
    const ROOT: &'static str = "queries";
    fn schema_issue(value: &serde_json::Value) -> Option<(String, serde_json::Value, serde_json::Value)> {
        let Some(kind) = value.get("kind").and_then(serde_json::Value::as_str) else { return Some((".kind".into(),value.get("kind").cloned().unwrap_or_default(),serde_json::json!(["nearest","overlap_sphere","sweep_sphere"]))); };
        let (allowed, required): (&[&str], &[&str]) = match kind {
            "nearest" => (&["kind","point","max_distance","mask","exclude_id"], &["kind","point","max_distance"]),
            "overlap_sphere" => (&["kind","center","radius","mask","exclude_id"], &["kind","center","radius"]),
            "sweep_sphere" => (&["kind","from","to","radius","mask","exclude_id"], &["kind","from","to","radius"]),
            _ => return Some((".kind".into(),serde_json::json!(kind),serde_json::json!(["nearest","overlap_sphere","sweep_sphere"]))),
        };
        record_issue(value, "", allowed, required)
    }
}

fn decode_array<T: DeserializeOwned + InputSchema>(value: Value, limit: usize) -> InputResult<Vec<T>> {
    let Value::Table(table) = value else { return Err(invalid("expected an array table", T::ROOT, value_fact(&value), serde_json::json!("array table"))); };
    if table.raw_len() > limit { return Err(invalid(format!("array count exceeds {limit}"), T::ROOT, serde_json::json!(table.raw_len()), serde_json::json!({"max_count":limit}))); }
    let mut value = to_json(Value::Table(table), 0, T::ROOT)?;
    if value.as_object().is_some_and(|object| object.is_empty()) { value = serde_json::Value::Array(Vec::new()); }
    let array: Vec<T> = serde_json::from_value(value.clone()).map_err(|message| {
        if let Some(array) = value.as_array() {
            for (index, record) in array.iter().enumerate() {
                if let Some((path,actual,expected)) = T::schema_issue(record) {
                    return invalid(message, &format!("{}[{}]{path}", T::ROOT,index+1), actual, expected);
                }
            }
        }
        invalid(message, T::ROOT, serde_json::json!({"type":if value.is_array(){"array"}else{"record"}}), serde_json::json!("array of valid records"))
    })?;
    if array.len() > limit { return Err(invalid(format!("array count exceeds {limit}"), T::ROOT, serde_json::json!(array.len()), serde_json::json!({"max_count":limit}))); }
    Ok(array)
}

fn bodies(value: Value) -> InputResult<Vec<SpatialBody>> {
    match value {
        Value::Buffer(buffer) => {
            let maximum = 8 + crate::spatial::MAX_BODIES * crate::spatial::PACKED_BODY_BYTES;
            if buffer.len() > maximum { return Err(invalid("packed body buffer exceeds limit", "bodies.byte_length", serde_json::json!(buffer.len()), serde_json::json!({"max":maximum}))); }
            unpack_bodies_detailed(&buffer.to_vec()).map_err(|mut issue| { issue.message = format!("SPATIAL_INPUT_INVALID: {}",issue.message); issue })
        }
        value => decode_array(value, crate::spatial::MAX_BODIES),
    }
}

fn handle(value: Value) -> InputResult<u64> {
    let actual = value_fact(&value);
    let number = match value { Value::Integer(value) => value as f64, Value::Number(value) => value, _ => f64::NAN };
    if !number.is_finite() || number <= 0.0 || number > MAX_SAFE_INTEGER || number.fract() != 0.0 {
        return Err(invalid("handle must be a positive safe integer", "handle", actual, serde_json::json!({"type":"integer","min":1,"max":9_007_199_254_740_991u64})));
    }
    Ok(number as u64)
}

fn boundary<T>(spatial: &Rc<RefCell<SpatialJobs>>, operation: &str, result: InputResult<T>, index: Option<u64>, ticket: Option<u64>) -> mlua::Result<T> {
    result.map_err(|mut issue| {
        if issue.path == "handle" { issue.path = if matches!(operation,"spatial.take"|"spatial.cancel") {"ticket"} else {"index"}.into(); }
        mlua::Error::RuntimeError(spatial.borrow().record_input(operation, issue, index, ticket))
    })
}

fn encode_json(lua: &Lua, value: serde_json::Value) -> mlua::Result<Value> { super::value::observation_json_to_lua(lua, value) }
fn encode<T: Serialize>(lua: &Lua, value: T) -> mlua::Result<Value> { encode_json(lua, serde_json::to_value(value).map_err(mlua::Error::external)?) }

struct BindingTimer { sample: SpatialBindingSample, started: Instant, phase: u8 }
impl BindingTimer {
    fn decoded(&mut self) { self.sample.input_decode_ms = self.started.elapsed().as_secs_f64()*1000.0; self.phase=0; }
    fn encoding(&mut self) { self.started=Instant::now(); self.phase=2; }
    fn finish(&mut self) {
        if self.phase==1 { self.sample.input_decode_ms=self.started.elapsed().as_secs_f64()*1000.0; }
        if self.phase==2 { self.sample.output_encode_ms=self.started.elapsed().as_secs_f64()*1000.0; }
    }
}
fn measured<T>(spatial: &Rc<RefCell<SpatialJobs>>, operation: &'static str, work: impl FnOnce(&mut BindingTimer)->mlua::Result<T>) -> mlua::Result<T> {
    let mut timer=BindingTimer { sample: SpatialBindingSample {operation,success:false,input_decode_ms:0.0,output_encode_ms:0.0,index:None,ticket:None}, started:Instant::now(),phase:1 };
    let result=work(&mut timer);timer.finish();timer.sample.success=result.is_ok();
    spatial.borrow_mut().record_binding(timer.sample);result
}

pub(super) fn bind(lua: &Lua, state: &ApiState) -> mlua::Result<Table> {
    let api = lua.create_table()?;
    let spatial = Rc::clone(&state.spatial);
    api.set("pack", lua.create_function(move |lua, value: Value| measured(&spatial,"spatial.pack",|timer| {
        let bodies: Vec<SpatialBody> = boundary(&spatial,"spatial.pack",decode_array(value,crate::spatial::MAX_BODIES),None,None)?;
        boundary(&spatial,"spatial.pack",validate_bodies_detailed(&bodies).map_err(|mut issue| {issue.message=format!("SPATIAL_INPUT_INVALID: {}",issue.message);issue}),None,None)?;
        timer.decoded();timer.encoding();
        lua.create_buffer(pack_bodies(&bodies).expect("validated bodies can be packed"))
    }))?)?;
    let spatial = Rc::clone(&state.spatial);
    api.set("create", lua.create_function(move |_, value: Value| measured(&spatial,"spatial.create",|timer| {
        let bodies = boundary(&spatial,"spatial.create",bodies(value),None,None)?;
        timer.decoded();let id=spatial.borrow_mut().create(bodies).map_err(mlua::Error::RuntimeError)?;
        timer.sample.index=Some(id);Ok(id as f64)
    }))?)?;
    let spatial = Rc::clone(&state.spatial);
    api.set("update", lua.create_function(move |_, (id,value):(Value,Value)| measured(&spatial,"spatial.update",|timer| {
        let id=boundary(&spatial,"spatial.update",handle(id),None,None)?;
        timer.sample.index=Some(id);
        let bodies=boundary(&spatial,"spatial.update",bodies(value),Some(id),None)?;
        timer.decoded();
        spatial.borrow_mut().update(id,bodies).map(|version|version as f64).map_err(mlua::Error::RuntimeError)
    }))?)?;
    let spatial = Rc::clone(&state.spatial);
    api.set("destroy", lua.create_function(move |_, id:Value| measured(&spatial,"spatial.destroy",|timer| {
        let id=boundary(&spatial,"spatial.destroy",handle(id),None,None)?;
        timer.sample.index=Some(id);timer.decoded();
        spatial.borrow_mut().destroy(id).map_err(mlua::Error::RuntimeError)
    }))?)?;
    let spatial = Rc::clone(&state.spatial);
    api.set("submit", lua.create_function(move |_, (id,value):(Value,Value)| measured(&spatial,"spatial.submit",|timer| {
        let context_index=handle(id.clone()).ok();
        timer.sample.index=context_index;
        let queries:Vec<SpatialQuery>=boundary(&spatial,"spatial.submit",decode_array(value,crate::spatial::MAX_QUERIES),context_index,None)?;
        let id=boundary(&spatial,"spatial.submit",handle(id),None,None)?;
        timer.decoded();let ticket=spatial.borrow_mut().submit(id,queries).map_err(mlua::Error::RuntimeError)?;
        timer.sample.ticket=Some(ticket);Ok(ticket as f64)
    }))?)?;
    let spatial = Rc::clone(&state.spatial);
    api.set("take", lua.create_function(move |lua,id:Value| measured(&spatial,"spatial.take",|timer| {
        let id=boundary(&spatial,"spatial.take",handle(id),None,None)?;
        timer.sample.ticket=Some(id);timer.decoded();
        let result=spatial.borrow_mut().take(id).map_err(mlua::Error::RuntimeError)?;
        timer.encoding();encode(lua,result)
    }))?)?;
    let spatial = Rc::clone(&state.spatial);
    api.set("cancel", lua.create_function(move |_,id:Value| measured(&spatial,"spatial.cancel",|timer| {
        let id=boundary(&spatial,"spatial.cancel",handle(id),None,None)?;
        timer.sample.ticket=Some(id);timer.decoded();
        spatial.borrow_mut().cancel(id).map_err(mlua::Error::RuntimeError)
    }))?)?;
    let spatial = Rc::clone(&state.spatial);
    api.set("info",lua.create_function(move |lua,()|encode(lua,spatial.borrow().info()))?)?;
    let spatial = Rc::clone(&state.spatial);
    api.set("profile",lua.create_function(move |lua,()|encode(lua,spatial.borrow().profile()))?)?;
    let spatial = Rc::clone(&state.spatial);
    api.set("lastDiagnostic",lua.create_function(move |lua,()|encode(lua,spatial.borrow().last_diagnostic()))?)?;
    Ok(api)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_arrays_and_full_unsigned_ids_are_portable() {
        let lua = Lua::new();
        let empty: Vec<SpatialBody> = decode_array(Value::Table(lua.create_table().unwrap()), 1).unwrap();
        assert!(empty.is_empty());
        let table = lua.load("return {{id=4294967295,position={1,2,3},radius=0,category=4294967295}}")
            .eval::<Value>().unwrap();
        let decoded: Vec<SpatialBody> = decode_array(table, 1).unwrap();
        assert_eq!(decoded[0].id, u32::MAX);
        assert_eq!(decoded[0].category, u32::MAX);
        assert!(matches!(encode(&lua, 9_007_199_254_740_991u64).unwrap(), Value::Number(n) if n == MAX_SAFE_INTEGER));
    }

    #[test]
    fn invalid_array_keys_unknown_fields_and_handles_are_rejected() {
        let lua = Lua::new();
        for source in [
            "return {[2]={id=1,position={0,0,0},radius=0}}",
            "return {[1]={id=1,position={0,0,0},radius=0},extra=1}",
            "return {{id=1,position={0,0,0},radius=0,team=2}}",
        ] {
            assert!(decode_array::<SpatialBody>(lua.load(source).eval().unwrap(), 5).is_err());
        }
        for value in [0.0, -1.0, f64::INFINITY, f64::NAN, 1.5, MAX_SAFE_INTEGER + 1.0] {
            assert!(handle(Value::Number(value)).is_err());
        }
    }
}

-- Unone public Luau contract.
--
-- This file is the engine's own copy and the single source of truth. A test
-- asserts every API in the engine's semantic index appears here, so the two
-- cannot drift. Write it into a project with:
--     game api typings --output <path>
-- project init inlines it into the entry script, because the engine runtime
-- has no module require: a single-file game must carry its own types for
-- `game check --types` to mean anything.
-- Official SDK-bundled Luau packages use typed API namespaces such as
-- api.ui.components; declare their exact runtime_packages versions in the project.
-- Refresh an existing marked type block without replacing game code with:
--     game --project <root> api typings --update-script <project-relative-script>
--
-- Game-owned models, ViewModels, Views and save schemas belong in the game.

export type Vec2 = { x: number, y: number }
export type Vec3 = { x: number, y: number, z: number }
export type Transform2D = { position: Vec2, rotation: number, scale: Vec2 }
export type Transform3D = { position: Vec3, rotation: Vec3, scale: Vec3 }
export type Camera3DTransform = { position: Vec3, target: Vec3, fovDegrees: number }

export type ObservationValue =
    nil
    | boolean
    | number
    | string
    | {[string]: ObservationValue}
    | {ObservationValue}

export type EntityApi = {
    spawn: (name: string) -> string,
    despawn: (id: string) -> (),
    setSpriteVisible: (id: string, visible: boolean) -> (),
    getPosition: (id: string) -> Vec2,
    setPosition: (id: string, position: Vec2) -> (),
    getVelocity: (id: string) -> Vec2,
    setVelocity: (id: string, velocity: Vec2) -> (),
    getTransform2D: (id: string) -> Transform2D,
    setTransform2D: (id: string, transform: Transform2D) -> (),
    getTransform3D: (id: string) -> Transform3D,
    setTransform3D: (id: string, transform: Transform3D) -> (),
}

export type HeightfieldDefinition = {
    width: number, depth: number, heights: {number}, cell_size: number,
    origin: Vec3, texture: string,
}
export type HeightfieldPatch = {x: number, z: number, width: number, depth: number, heights: {number}}
export type HeightfieldApi = {
    -- Native presentation geometry; no collision or game-owned editing rules.
    -- Row-major X-fast samples; update rectangles use zero-based sample indices.
    set: (id: string, definition: HeightfieldDefinition) -> (),
    update: (id: string, patch: HeightfieldPatch) -> (),
    remove: (id: string) -> (),
}

export type Instances3DApi = {
    -- Packed little-endian f32 records: position.xyz, quaternion.xyzw, scale.xyz (40 bytes).
    -- Replaces a complete batch atomically; max 262144 instances / 256 batches per world.
    set: (id: string, asset: string, transforms: buffer) -> (),
    remove: (id: string) -> (),
}

export type EscapeBehavior = "action" | "quit"
export type ApplicationApi = {
    -- Defaults to quit. Action mode publishes neutral Escape input for game policy.
    setEscapeBehavior: (behavior: EscapeBehavior) -> (),
    -- Monotonic host intent; native exits after successfully presenting this state.
    -- The game owns confirmation. Headless records the latch without GPU evidence.
    requestQuit: () -> (),
}

export type InputApi = {
    -- Current-tick host-projected UI event. Prefer createSlider().update(input).
    getSliderInteraction: (id: string) -> UiSliderInteraction?,
    isDown: (action: string) -> boolean,
    -- Non-consuming edges for the current simulation tick. Read in update;
    -- multiple reads return the same result. Held actions press only once.
    wasPressed: (action: string) -> boolean,
    wasReleased: (action: string) -> boolean,
    getPointerPosition: () -> Vec2,
    getScreenPointerPosition: () -> Vec2,
    isPointerDown: () -> boolean,
}

export type RandomApi = {
    nextFloat: () -> number,
    nextInt: (min: number, max: number) -> number,
}

export type PhysicsApi = {
    applyImpulse: (id: string, impulse: Vec2) -> (),
}
export type SphereSweepTarget = { id: string, radius: number, previous_position: Vec3 }
export type SphereSweepHit = { id: string, fraction: number, point: Vec3, normal: Vec3 }
export type Physics3DApi = {
    getBody: (id: string) -> Body3D,
    addBody: (id: string, body: Body3D) -> (),
    removeBody: (id: string) -> (),
    setGravity: (value: Vec3) -> (),
    setVelocity: (id: string, value: Vec3) -> (),
    setAngularVelocity: (id: string, value: Vec3) -> (),
    applyImpulse: (id: string, value: Vec3) -> (),
    applyTorqueImpulse: (id: string, value: Vec3) -> (),
    addForce: (id: string, value: Vec3) -> (),
    addTorque: (id: string, value: Vec3) -> (),
    clearForces: (id: string) -> (),
    teleport: (id: string, pose: Pose3D) -> (),
    moveKinematic: (id: string, pose: Pose3D) -> (),
    raycast: (request: {from: Vec3, to: Vec3, filter: QueryFilter3D?}) -> SphereSweepHit?,
    castShape: (request: {pose: Pose3D, to: Vec3, shape: Shape3D, filter: QueryFilter3D?}) -> SphereSweepHit?,
    overlap: (request: {pose: Pose3D, shape: Shape3D, filter: QueryFilter3D?}) -> {string},
    snapshot: () -> any,
    contacts: () -> {{a: string,b: string,sensor: boolean,normal: Vec3,impulse: number,phase: string}},
    addJoint: (id: string, joint: {body_a:string,body_b:string,anchor_a:Vec3,anchor_b:Vec3,joint:JointKind3D,contacts_enabled:boolean?}) -> (),
    removeJoint: (id: string) -> (),
    sweepSphere: (request: { from: Vec3, to: Vec3, radius: number, targets: {SphereSweepTarget} }) -> SphereSweepHit?,
}
export type Pose3D = {position:Vec3,rotation:Vec3?}
export type Shape3D = {kind:"sphere",radius:number} | {kind:"box",half_extents:Vec3} | {kind:"capsule",half_height:number,radius:number} | {kind:"convex",vertices:{Vec3}} | {kind:"trimesh",vertices:{Vec3},indices:{{number}}}
export type Body3D = {body_type:"dynamic"|"static"|"kinematic",shape:Shape3D,mass:number?,velocity:Vec3?,angular_velocity:Vec3?,friction:number?,restitution:number?,linear_damping:number?,angular_damping:number?,gravity_scale:number?,sensor:boolean?,ccd:boolean?,lock_rotation:boolean?,can_sleep:boolean?,membership:number?,filter:number?}
export type QueryFilter3D = {membership:number?,filter:number?,exclude:string?,include_sensors:boolean?}
export type JointKind3D = {kind:"fixed"}|{kind:"spherical"}|{kind:"revolute",axis:Vec3,limits:{number}?}

export type CameraApi = {
    -- Canonical Unity-like camera: one 3D transform plus a projection mode.
    -- `orthographic` is the 2D-compatible projection; `perspective` is the
    -- regular 3D projection. The old 2D calls below remain compatibility
    -- helpers and should not be used to model a second camera.
    getProjection: () -> ("orthographic" | "perspective"),
    setProjection: (projection: "orthographic" | "perspective") -> (),
    getTransform: () -> CameraTransform,
    setTransform: (transform: CameraTransformInput) -> (),
    getPosition: () -> Vec2,
    setPosition: (position: Vec2) -> (),
    getZoom: () -> number,
    setZoom: (zoom: number) -> (),
}

export type CameraTransform = {
    projection: "orthographic" | "perspective",
    position: Vec3,
    target: Vec3,
    fovDegrees: number?,
    orthographicSize: number?,
}

export type CameraTransformInput = {
    projection: ("orthographic" | "perspective")?,
    position: Vec3,
    target: Vec3?,
    fovDegrees: number?,
    orthographicSize: number?,
}

export type Camera3DApi = {
    getTransform: () -> Camera3DTransform,
    setPosition: (position: Vec3) -> (),
    setTarget: (target: Vec3) -> (),
}

export type ObservationApi = {
    set: (key: string, value: ObservationValue) -> (),
    array: ((values: nil) -> {ObservationValue}) & (<T>(values: {T}) -> {T}),
    setArray: <T>(key: string, values: {T}?) -> (),
}

-- The UI design space is 0..100 on both axes and **y points UP**: y = 0 is the
-- bottom of the screen, y = 100 the top, and a rect grows upward from its y.
-- Most UI systems are y-down, so this is the single easiest thing to get wrong
-- when you cannot see the screen.
--
-- A UI node declares its placement exactly one of two ways.
--
-- `rect` is absolute in the 0..100 design space; use it when the layout is not
-- edge relative, such as a ring laid out with trigonometry.
--
-- `anchor` + `size` (+ optional `offset` and `pivot`) is edge relative. Its
-- numbers are vertical units on both axes -- percent of the viewport height --
-- so a box keeps its shape and its distance from the edge on any screen shape.
-- The engine resolves it against the viewport the host reports.
export type UiAnchor =
    "top_left" | "top" | "top_right"
    | "left" | "center" | "right"
    | "bottom_left" | "bottom" | "bottom_right"

export type UiApi = {
    components: UiComponentsApi,
    setRoot: (root: UiScreen) -> (),
    -- Current host width/height ratio, also used by anchored placement.
    -- Read-only environment data; pass to components.createResponsiveLayout().resolve.
    getViewport: () -> {aspect: number},
    -- Helpers return a real scroll_view node. Content is local top-left/y-down;
    -- viewport uses explicit left/top; never pass a stage x/y rect here.
    scrollView: (options: UiScrollOptions) -> UiScrollNode,
    virtualList: <T>(options: UiVirtualOptions<T>) -> UiScrollNode,
    virtualGrid: <T>(options: UiVirtualGridOptions<T>) -> UiScrollNode,
    -- Actual host ceilings and the last valid tree's node/subtree usage.
    inspect: () -> ObservationValue,
}
export type UiRect = {x: number, y: number, width: number, height: number}
-- Every style length uses vertical units (1 = 1% of viewport height).
-- Styles belong to one leaf, with no implicit inheritance. An explicit
-- font_size does not change when its box changes and never silently shrinks.
export type UiColor = {number} -- exactly four RGBA values, each in 0..1
export type UiInsets = {left: number?, top: number?, right: number?, bottom: number?}
export type UiStyle = {
    font_family: string?, font_size: number?, font_weight: number?,
    line_height: number?, letter_spacing: number?, color: UiColor?,
    text_align: ("start" | "center" | "end")?,
    vertical_align: ("top" | "middle" | "bottom")?,
    wrap: ("none" | "word")?, overflow: ("clip" | "ellipsis")?,
    padding: UiInsets?, background: UiColor?, border_color: UiColor?,
    border_width: number?, border_radius: number?, opacity: number?,
}
export type UiPlacement = {
    rect: UiRect?, anchor: UiAnchor?, pivot: UiAnchor?,
    offset: {x: number?, y: number?}?, size: {width: number, height: number}?,
}
export type UiTextNode = UiPlacement & {
    kind: "text", id: string, text: string?, style: UiStyle?,
}
export type UiButtonNode = UiPlacement & {
    kind: "button", id: string, text: string?, action: string, style: UiStyle?,
}
export type UiSliderNode = UiPlacement & {
    kind: "slider", id: string, text: string?, action: string, style: UiStyle?,
    drag: UiSliderDrag?,
}
export type UiSliderInteraction = {phase: "start" | "drag" | "end" | "cancel", ratio: number}
export type UiSliderDrag = {
    axis: "horizontal" | "vertical", reverse: boolean, enabled: boolean,
    track_rect: UiRect, hit_rect: UiRect,
}
export type UiSliderOptions = {
    id: string, value: number, min: number?, max: number?, step: number?,
    axis: ("horizontal" | "vertical")?, reverse: boolean?,
    onChange: never?, onClick: never?,
}
-- Explicit rects in the node's current stage/scroll space; no duplicate pointer
-- mapping in projects. Hosts project, clip and capture these together.
export type UiSliderViewProps = {
    rect: UiRect, trackRect: UiRect?, hitPadding: number?, enabled: boolean?,
    text: string?, action: string?, style: UiStyle?,
    onChange: never?, value: never?,
}
export type UiSliderUpdate = {
    value: number, changed: boolean, dragging: boolean,
    started: boolean, released: boolean, cancelled: boolean,
}
export type UiSliderControl = {
    view: (props: UiSliderViewProps) -> UiSliderNode,
    update: (input: InputApi) -> UiSliderUpdate,
    getValue: () -> number,
    setValue: (value: number) -> (),
    cancel: () -> (),
}
export type UiComboBoxNode = UiPlacement & {
    kind: "combobox", id: string, text: string?, action: string,
    expanded: boolean?, style: UiStyle?,
}
-- Image and panel styles accept box fields; typography requires a text leaf.
-- A decorative surface may explicitly belong to its screen or an ancestor
-- component in the same coordinate space. This never changes placement/order.
export type UiBackgroundScope = {screen: true} | {component: string}
export type UiImageNode = UiPlacement & {
    kind: "image", id: string, asset: string, fit: ("contain" | "cover" | "stretch")?,
    alt: string?, slice: UiSlice?, style: UiStyle?, background_for: UiBackgroundScope?,
}
export type UiPanelNode = UiPlacement & {
    kind: "panel", id: string, style: UiStyle?, background_for: UiBackgroundScope?,
}
export type UiComponentNode = UiPlacement & {
    -- Grouping does not transform children: their coordinates remain in the
    -- current stage/scroll space, with no relative-placement or style inheritance.
    kind: "component", id: string, component: string, children: {UiNode}?,
}
export type UiScrollNode = UiPlacement & {
    kind: "scroll_view", id: string, viewport: UiViewport?,
    scroll: {axis: string?, enabled: boolean?, inertia: boolean?, deceleration: number?, reset_key: string?, wheel_rect: UiRect?, virtual_items: any?},
    children: {UiNode}?,
}
export type UiNode = UiTextNode | UiButtonNode | UiSliderNode | UiComboBoxNode
    | UiImageNode | UiPanelNode | UiComponentNode | UiScrollNode
export type UiScreen = {kind: "screen", id: string, node: string, children: {UiNode}, budget: UiBudget?}
-- @unone/ui: pure constructors and explicitly selected declarative layout.
-- create snapshots these defaults; leaf overrides win, padding merges per edge.
export type UiComponentsTheme = {
    text: UiStyle?, button: UiStyle?, panel: UiStyle?, image: UiStyle?,
    slider: UiStyle?, combobox: UiStyle?,
}
export type UiComponentTextProps = UiPlacement & {
    id: string, text: string?, style: UiStyle?,
}
export type UiComponentButtonProps = UiPlacement & {
    id: string, text: string?, action: string, style: UiStyle?,
}
-- Common invented value/binding props are absent; state belongs to the project.
-- Unknown fields and placement combinations still require runtime validation.
export type UiComponentSliderProps = UiPlacement & {
    value: never?, min: never?, max: never?, step: never?, onChange: never?,
    id: string, text: string?, action: string, style: UiStyle?,
}
export type UiComponentComboBoxProps = UiPlacement & {
    value: never?, options: never?, selected: never?, onChange: never?,
    id: string, text: string?, action: string, expanded: boolean?, style: UiStyle?,
}
export type UiComponentPanelProps = UiPlacement & {
    id: string, style: UiStyle?, background_for: UiBackgroundScope?,
}
export type UiComponentImageProps = UiPlacement & {
    id: string, asset: string, fit: ("contain" | "cover" | "stretch")?,
    alt: string?, slice: UiSlice?, style: UiStyle?, background_for: UiBackgroundScope?,
}
export type UiComponentSurface = {
    kind: "panel", style: UiStyle?,
} | {
    kind: "image", asset: string, fit: ("contain" | "cover" | "stretch")?,
    alt: string?, slice: UiSlice?, style: UiStyle?,
}
export type UiComponentProps = UiPlacement & {
    id: string, component: string, children: {UiNode}?, surface: UiComponentSurface?,
}
export type UiComponentScreenProps = {
    id: string, node: string, children: {UiNode}, budget: UiBudget?,
}
-- Layout lengths use normalized stage units per axis, like rect/viewport.
-- They are NOT font/anchor vertical units. No intrinsic text measurement.
-- A recursive record preserves contextual literal inference in strict Luau.
-- The factory validates kind-dependent fields (grid columns, slot children,
-- root sizing) and reports UI_LAYOUT_* errors before publishing anything.
export type UiLayoutNode = {
    id: string, kind: "slot" | "row" | "column" | "grid",
    size: number?, grow: number?, children: {UiLayoutNode}?,
    gap: number?, padding: UiInsets?, columns: number?,
    rect: never?, style: never?, flex: never?, wrap: never?, direction: never?,
}
export type UiResponsiveVariant<T> = {
    name: string, minAspect: number, layout: UiLayoutNode, values: T,
}
export type UiResponsiveLayoutOptions<T> = {
    space: ("stage" | "scroll")?, variants: {UiResponsiveVariant<T>},
    onResize: never?, breakpoints: never?,
}
export type UiResponsiveLayoutResult<T> = {
    variant: string, values: T,
    -- Fresh canonical copies; stage rect is y-up, scroll rect is y-down.
    rect: (id: string) -> UiRect,
    -- Top-left/y-down in either space; suitable for ScrollView viewport.
    viewport: (id: string) -> UiViewport,
}
export type UiResponsiveLayout<T> = {
    -- Pure: highest minAspect <= viewport.aspect, fallback first (minAspect=0).
    -- Stage bounds stay inside 0..100; scroll bounds may extend beyond 100.
    resolve: (viewport: {aspect: number}, bounds: UiViewport?) -> UiResponsiveLayoutResult<T>,
}
export type UiComponentKit = {
    -- Create once with authored groups/thresholds; resolve each View for reflow.
    createResponsiveLayout: <T>(options: UiResponsiveLayoutOptions<T>) -> UiResponsiveLayout<T>,
    -- Preferred complete numeric slider: reusable state plus semantic host capture.
    createSlider: (options: UiSliderOptions) -> UiSliderControl,
    text: (props: UiComponentTextProps) -> UiTextNode,
    button: (props: UiComponentButtonProps) -> UiButtonNode,
    slider: (props: UiComponentSliderProps) -> UiSliderNode,
    combobox: (props: UiComponentComboBoxProps) -> UiComboBoxNode,
    panel: (props: UiComponentPanelProps) -> UiPanelNode,
    image: (props: UiComponentImageProps) -> UiImageNode,
    component: (props: UiComponentProps) -> UiComponentNode,
    screen: (props: UiComponentScreenProps) -> UiScreen,
    -- Same engine-owned live helpers as UiApi. Scroll content is local
    -- top-left/y-down; the viewport uses left/top/width/height.
    scrollView: (options: UiScrollOptions) -> UiScrollNode,
    virtualList: <T>(options: UiVirtualOptions<T>) -> UiScrollNode,
    virtualGrid: <T>(options: UiVirtualGridOptions<T>) -> UiScrollNode,
    id: (instanceId: string, role: string) -> string,
    composeStyle: (base: UiStyle?, override: UiStyle?) -> UiStyle,
}
export type UiComponentsInfo = {
    name: string, version: string, kind: string, entry: string,
    api: string, license: string, declared: boolean,
}
-- Direct constructors use default styles. create(theme) supplies the same
-- constructor methods with explicitly authored per-kind style defaults.
export type UiComponentsApi = UiComponentKit & {
    info: () -> UiComponentsInfo,
    create: (theme: UiComponentsTheme?) -> UiComponentKit,
    composeStyle: (base: UiStyle?, override: UiStyle?) -> UiStyle,
    id: (instanceId: string, role: string) -> string,
}
export type UiViewport = {left: number, top: number, width: number, height: number}
export type UiScrollOptions = {
    id: string, viewport: UiViewport, content: {UiNode}?,
    axis: ("vertical" | "horizontal" | "both")?, enabled: boolean?,
    resetKey: string?, wheelRect: UiViewport?,
    inertia: boolean?, deceleration: number?,
}
-- Give T your project row type to check keys and render callbacks.
-- Bare options keep the legacy any default for existing projects.
export type UiVirtualOptions<T = any> = {
    id: string, viewport: UiViewport, items: {T}, key: string | ((T, number) -> string),
    rowHeight: number, gapY: number?,
    renderItem: (T, number, string) -> {UiNode},
    enabled: boolean?, resetKey: string?, wheelRect: UiViewport?,
    inertia: boolean?, deceleration: number?,
}
export type UiVirtualGridOptions<T = any> = UiVirtualOptions<T> & {
    columns: number, columnWidth: number, gapX: number?,
}

-- One source texture and one node. Border pixels / pixels_per_unit become
-- vertical design units; optional source is a y-down pixel crop, not UI rect.
export type UiSlice = {
    left: number, top: number, right: number, bottom: number,
    pixels_per_unit: number,
    source: {x: number, y: number, width: number, height: number}?,
}
export type UiBudget = {max_nodes: number}

export type SaveApi = {
    set: (value: ObservationValue) -> (),
    get: () -> ObservationValue,
}

export type AnimationOptions = {
    asset: string?,
    loop: boolean?,
    speed: number?,
}

-- Semantic skeletal animation state. The engine stores the selection; the
-- host runs the Spine runtime. Requires system "spine".
export type AnimationApi = {
    play: (id: string, name: string, options: AnimationOptions?) -> (),
    stop: (id: string) -> (),
}

export type EffectOptions = {
    x: number?,
    y: number?,
    scale: number?,
    rotation: number?,
}

-- Semantic effect events. The engine stores live instances; the host runs the
-- Effekseer runtime. Requires system "effekseer".
export type EffectApi = {
    spawn: (asset: string, options: EffectOptions?) -> string,
    stop: (handle: string) -> boolean,
}

export type AudioOptions = {
    volume: number?,
    speed: number?,
    category: string?,
    x: number?,
    y: number?,
    -- Attach the sound to an entity; the engine keeps it on that entity and
    -- stops it when the entity is gone.
    entity: string?,
}

-- Semantic audio requests. The engine owns which sound starts, which one a
-- category switch stops, and the exact frame a fade ends; the host decodes and
