        };
        if ui_score.is_some() {
            return ui_score;
        }
        // Shared visual terms may also describe world APIs. Keep those normal
        // matches available: e.g. "entity size" must not become UI-only.
        if !matches!(
            term,
            "color"
                | "colour"
                | "background"
                | "opacity"
                | "radius"
                | "weight"
                | "size"
                | "line"
                | "height"
                | "overlap"
                | "overlaps"
        ) {
