// Official host adapter. CPU uses the Rust reference; WebGPU is an explicit policy.
import {readObservation} from './load-project.js';
import {createSpatialHostMetrics} from './spatial-metrics.mjs';

export function createSpatialHost(module, {backend='cpu', createExecutor}={}) {
  if (!['cpu','gpu','auto'].includes(backend)) throw Error('SPATIAL_BACKEND_INVALID');
  let executor=null, pending=Promise.resolve(), fault=null, closed=false, epoch=0;
  let status={requested:backend, backend:'cpu', fallback_reason:null};
  const metrics=createSpatialHostMetrics();
  function request(value) {
    const sample={success:false,request_bytes:0,response_bytes:0,json_encode_ms:0,copy_in_ms:0,abi_ms:0,response_decode_ms:0};
    let started=performance.now(),phase='json_encode_ms';
    try {
      if (typeof module._unone_web_spatial_request!=='function') throw Error('SPATIAL_ABI_UNAVAILABLE: rebuild the Web runtime');
      const bytes=new TextEncoder().encode(JSON.stringify(value));sample.request_bytes=bytes.length;
      sample.json_encode_ms=performance.now()-started;phase=null;
      if(bytes.length>16*1024*1024) throw Error('SPATIAL_HOST_PAYLOAD_INVALID');
      started=performance.now();phase='copy_in_ms';
      const pointer=module._unone_web_alloc(bytes.length);module.HEAPU8.set(bytes,pointer);
      sample.copy_in_ms=performance.now()-started;
      started=performance.now();phase='abi_ms';const code=module._unone_web_spatial_request(pointer,bytes.length);
      sample.abi_ms=performance.now()-started;
      started=performance.now();phase='response_decode_ms';
      sample.response_bytes=module._unone_web_observation_len();const response=readObservation(module);
      sample.response_decode_ms=performance.now()-started;phase=null;
      if(code!==0) throw Error(JSON.stringify(response));
      sample.success=true;return response;
    } finally {
      if(phase)sample[phase]=performance.now()-started;
      metrics.request(value.kind,sample);
    }
  }
  return {
    async load() {
      // A load retires an entire executor epoch; an old completion cannot enter it.
      ++epoch; await pending; executor?.close(); executor=null; fault=null; closed=false;
      metrics.reset();
      status={requested:backend,backend:'cpu',fallback_reason:null};
      const setupStarted=performance.now();let createMs=0,configureMs=0,createStarted=null,configureStarted=null;
      if(backend==='cpu') {metrics.setup({success:true,total_ms:performance.now()-setupStarted,executor_create_ms:0,configure_ms:0,gpu_initialized:false});return;}
      try {
        if(typeof module._unone_web_spatial_request!=='function') throw Error('SPATIAL_ABI_UNAVAILABLE: rebuild the Web runtime');
        const create=createExecutor??(await import('./spatial-gpu.mjs')).createSpatialGpuExecutor;
        createStarted=performance.now();executor=await create();createMs=performance.now()-createStarted;createStarted=null;
        configureStarted=performance.now();
        request({kind:'configure',backend:'webgpu'});
        configureMs=performance.now()-configureStarted;configureStarted=null;
      } catch(error) {
        if(createStarted!==null)createMs=performance.now()-createStarted;
        if(configureStarted!==null)configureMs=performance.now()-configureStarted;
        metrics.setup({success:false,total_ms:performance.now()-setupStarted,executor_create_ms:createMs,configure_ms:configureMs,gpu_initialized:false});
        executor?.close();executor=null;
        if(backend==='gpu') throw error;
        status.fallback_reason=String(error.message??error);return;
      }
      status.backend='webgpu';
      metrics.setup({success:true,total_ms:performance.now()-setupStarted,executor_create_ms:createMs,configure_ms:configureMs,gpu_initialized:true});
    },
    dispatch() {
      if(!executor) return;
      const tasks=request({kind:'drain'}), generation=epoch;
      if(!Array.isArray(tasks)) throw Error('SPATIAL_HOST_RESPONSE_INVALID');
      pending=pending.then(async()=>{
        for(const task of tasks) {
          if(closed||generation!==epoch)return;
          const result=await executor.execute(task.batch);
          if(closed||generation!==epoch)return;
          const profile=typeof executor.profile==='function'?executor.profile():null;
          request({kind:'complete',id:task.id,result,...(profile==null?{}:{profile})});
        }
      }).catch(error=>{
        if(closed||generation!==epoch)return;
        fault=error;
        try{request({kind:'fault',message:String(error.message??error)});}catch{/* preserve original GPU error */}
      });
    },
    async barrier(){await pending;if(fault)throw fault;},
    diagnostic(){return request({kind:'diagnostic'});},
    report(){return {...status,fault:fault?String(fault):null,profile:typeof executor?.profile==='function'?structuredClone(executor.profile()):null,metrics:metrics.report()};},
    close(){closed=true;++epoch;executor?.close();executor=null;},
  };
}

// Detached, bounded host diagnostics. Nothing here affects fixed-tick delivery.
const kinds=['configure','drain','complete','report','profile','fault','diagnostic'];
const phases=['json_encode_ms','copy_in_ms','abi_ms','response_decode_ms'];
const safe=Number.MAX_SAFE_INTEGER;
const add=(a,b)=>Math.min(safe,a+b);
const number=value=>typeof value==='number'&&Number.isFinite(value)&&value>=0;
function empty(){return {requests:0,failed_requests:0,request_bytes:0,response_bytes:0,...Object.fromEntries(phases.map(p=>[p,0]))};}
export function createSpatialHostMetrics(){
 let setup=null,totals=empty(),byKind={};
 return {
  reset(){setup=null;totals=empty();byKind={};},
  setup(sample){
   for(const p of ['total_ms','executor_create_ms','configure_ms'])if(!number(sample[p]))throw Error('SPATIAL_METRIC_INVALID');
   setup={...sample};
  },
  request(kind,sample){
   if(!kinds.includes(kind)||!['request_bytes','response_bytes',...phases].every(p=>number(sample[p])))throw Error('SPATIAL_METRIC_INVALID');
   const entry=byKind[kind]??=empty();
   for(const target of [totals,entry]){
    target.requests=add(target.requests,1);if(!sample.success)target.failed_requests=add(target.failed_requests,1);
    for(const p of ['request_bytes','response_bytes',...phases])target[p]=add(target[p],sample[p]);
   }
  },
  report(){return structuredClone({api_version:1,clock:'host_monotonic',scope:'Since latest host load. JSON encode includes stringify/TextEncoder; copy_in covers WASM allocation/copy; abi includes the synchronous WASM request and its internal serialization, not GPU execution; response_decode covers readObservation copy/TextDecoder/JSON parse. Setup includes executor creation/configuration; configure_ms overlaps bridge configure timings. Excludes project load, Worker messaging, caller application and report cloning. Failed request metrics include only phases reached.',setup,bridge:{totals,by_kind:byKind}});},
 };
}

// Engine-owned WebGPU executor for the canonical spatial batch protocol.
// v1 scans one body array per query and reads back results. It has no gameplay
// dependencies and makes no claim of outperforming the CPU at small batch sizes.
const BODY_WORDS=12, QUERY_WORDS=16, HIT_WORDS=12, RESULT_WORDS=772;
const MAX_BODIES=65536, MAX_QUERIES=1024, MAX_HITS=64, LIMIT=1e6;
const u32=(value,label)=>{if(!Number.isInteger(value)||value<0||value>0xffffffff)throw Error(`${label} must be a u32`);return value;};
const scalar=(value,label)=>{if(typeof value!=='number'||!Number.isFinite(value)||Math.fround(value)<0||Math.fround(value)>LIMIT)throw Error(`${label} must be finite and in [0, ${LIMIT}]`);return value;};
const distance=(value,label)=>{if(typeof value!=='number'||!Number.isFinite(Math.fround(value))||Math.fround(value)<0)throw Error(`${label} must be a finite nonnegative f32`);return value;};
const coordinate=n=>typeof n==='number'&&Number.isFinite(n)&&Math.abs(Math.fround(n))<=LIMIT;
const vector=(value,label)=>{if(!Array.isArray(value)||value.length!==3||!coordinate(value[0])||!coordinate(value[1])||!coordinate(value[2]))throw Error(`${label} must contain three finite coordinates in [-${LIMIT}, ${LIMIT}]`);return value;};
function fields(value,allowed,label){if(!value||typeof value!=='object'||Array.isArray(value))throw Error(`${label} must be an object`);for(const key of Object.keys(value))if(!allowed.includes(key))throw Error(`${label}: unknown field ${key}`);}

/** Validates a public batch before allocating GPU resources. */
export function validateSpatialGpuBatch(batch){
 fields(batch,['version','bodies','queries'],'batch');u32(batch.version,'version');
 if(!Array.isArray(batch.bodies)||batch.bodies.length>MAX_BODIES)throw Error(`bodies must be an array of at most ${MAX_BODIES}`);
 if(!Array.isArray(batch.queries)||batch.queries.length>MAX_QUERIES)throw Error(`queries must be an array of at most ${MAX_QUERIES}`);
 const ids=new Set();for(const body of batch.bodies){fields(body,['id','position','radius','category','previous_position'],'body');u32(body.id,'body.id');if(ids.has(body.id))throw Error(`duplicate body id ${body.id}`);ids.add(body.id);vector(body.position,'body.position');scalar(body.radius,'body.radius');u32(body.category===undefined?1:body.category,'body.category');if(body.previous_position!=null)vector(body.previous_position,'body.previous_position');}
 for(const query of batch.queries){
  const common=['kind','mask','exclude_id'];
  if(query?.kind==='nearest'){fields(query,[...common,'point','max_distance'],'query');vector(query.point,'query.point');distance(query.max_distance,'query.max_distance');}
  else if(query?.kind==='overlap_sphere'){fields(query,[...common,'center','radius'],'query');vector(query.center,'query.center');scalar(query.radius,'query.radius');}
  else if(query?.kind==='sweep_sphere'){fields(query,[...common,'from','to','radius'],'query');vector(query.from,'query.from');vector(query.to,'query.to');scalar(query.radius,'query.radius');}
  else throw Error(`unsupported spatial query kind: ${query?.kind}`);
  u32(query.mask===undefined?0xffffffff:query.mask,'query.mask');if(query.exclude_id!=null)u32(query.exclude_id,'query.exclude_id');
 }
 return batch;
}

/** Shared wire layout, exported for host contract tests and offline inspection. */
export function packSpatialGpuBatch(batch){
 validateSpatialGpuBatch(batch);
 return packValidatedBatch(batch);
}

function packValidatedBatch(batch){
 const bodies=new Uint32Array(Math.max(1,batch.bodies.length)*BODY_WORDS),bf=new Float32Array(bodies.buffer);
 for(let i=0;i<batch.bodies.length;i++){const b=batch.bodies[i],o=i*BODY_WORDS;bodies[o]=b.id;bodies[o+1]=b.category??1;bf[o+2]=b.radius;bf.set(b.position,o+4);bf.set(b.previous_position??b.position,o+8);}
 const queries=new Uint32Array(batch.queries.length*QUERY_WORDS),qf=new Float32Array(queries.buffer);
 for(let i=0;i<batch.queries.length;i++){const q=batch.queries[i],o=i*QUERY_WORDS;queries[o]=q.kind==='nearest'?0:q.kind==='overlap_sphere'?1:2;queries[o+1]=q.mask??0xffffffff;queries[o+2]=q.exclude_id??0;queries[o+3]=q.exclude_id==null?0:1;qf.set(q.point??q.center??q.from,o+4);qf[o+7]=q.radius??0;qf.set(q.to??[0,0,0],o+8);qf[o+11]=q.max_distance??0;}
 return {bodies,queries,params:new Uint32Array([batch.bodies.length,batch.queries.length,0,0])};
}

export function decodeSpatialGpuResults(version,count,buffer){
 const words=new Uint32Array(buffer),floats=new Float32Array(buffer);
 if(words.length!==count*RESULT_WORDS)throw Error('spatial GPU result byte length mismatch');
 const results=[];for(let i=0;i<count;i++){const base=i*RESULT_WORDS;if(words[base+1])throw Error(`spatial overlap query ${i} exceeds ${MAX_HITS} hits`);if(words[base]>MAX_HITS)throw Error('spatial GPU result count is invalid');const hits=[];for(let slot=0;slot<words[base];slot++){const o=base+4+slot*HIT_WORDS;hits.push({id:words[o],distance:floats[o+1],fraction:floats[o+2],point:Array.from(floats.subarray(o+4,o+7)),normal:Array.from(floats.subarray(o+8,o+11))});}results.push({hits});}
 return {version,results};
}

/** Creates a real WebGPU compute executor. A supplied device remains host-owned. */
export async function createSpatialGpuExecutor({device,shaderSource}={}){
 let ownsDevice=false,adapterInfo=null;
 if(!device){if(!globalThis.navigator?.gpu)throw Error('spatial WebGPU is unavailable');const adapter=await navigator.gpu.requestAdapter();if(!adapter)throw Error('spatial WebGPU adapter is unavailable');adapterInfo=adapter.info??null;device=await adapter.requestDevice();ownsDevice=true;}
